function muz(){if(!state.musas||typeof state.musas!=='object')state.musas={dons:{},day:{}};return state.musas;}
function divineFigure(x,z,look,col,name,sub,scale,skinCol){const g=makePerson(Object.assign({noVary:true,scale:scale||1.15,glow:skinCol||col},look));g.position.set(x,floorAt(x,z),z);scene.add(g);
  const h=new THREE.Sprite(new THREE.SpriteMaterial({map:HALO_TEX,blending:THREE.AdditiveBlending,depthWrite:false,transparent:true,opacity:0.7,fog:false,color:col}));h.scale.set(3.2,4.2,1);h.position.y=1.05;g.add(h);
  const lb=labelSprite(name,sub,false);lb.position.y=2.5;lb.visible=false;g.add(lb);const mk=markerSprite();mk.position.y=2.95;g.add(mk);return{g,lb,mk};}
function buildMusas(){MUSE_OBJS.length=0;
  for(const m of MUSAS()){const p=stAnchor(m.at);if(!p)continue;const f=findFree(p.x+5,p.z+5,0.8);const F=divineFigure(f[0],f[1],m.look,'#7fffd4',m.name,'musa de '+m.arte,undefined,'#a6eedc');F.g.traverse(o=>{if(o.isSprite&&o.material.blending===THREE.AdditiveBlending){o.material.opacity=1;o.scale.set(3.8,4.8,1);}});   // las Musas brillan en aguamarina; los dioses, en dorado
    F.g.rotation.y=R()*TAU;F.mk.visible=!muz().dons[m.id];MUSE_OBJS.push({kind:'musa',x:f[0],z:f[1],g:F.g,lb:F.lb,mk:F.mk,m,data:{name:m.name,role:'musa'}});}
  const M=MNEMO[MODE==='roma'?'R':'A'],p=stAnchor(M.at);
  if(p){const f=findFree(p.x+6,p.z-4,0.8);const F=divineFigure(f[0],f[1],{female:true,chiton:'#1f2a4a',himation:'#3a4a7a',veil:true,hair:'#d8d0c2'},'#b8c8ff','Mnemósine','titánide de la memoria, madre de las Musas',1.3);
    OLYM.mnemo={kind:'mnemo',x:f[0],z:f[1],g:F.g,lb:F.lb,mk:F.mk,data:{name:'Mnemósine',role:'madre de las Musas'}};F.mk.visible=Object.keys(muz().dons).length>=9&&!state.olyKey;}
  const gp=stAnchor(OLY_GATE[MODE==='roma'?'R':'A']);
  if(gp){const f=findFree(gp.x-8,gp.z+6,1.2);const g=grp(f[0],floorAt(f[0],f[1]),f[1],0);
    box(1.2,4,1.2,M.limestone,0,2,0,g);const s=new THREE.Sprite(new THREE.SpriteMaterial({map:HALO_TEX,blending:THREE.AdditiveBlending,depthWrite:false,transparent:true,opacity:0.6,fog:false,color:'#fff4c0'}));s.scale.set(4,8,1);s.position.y=4.5;g.add(s);
    const lb=labelSprite('Sendero del Olimpo','un camino que se pierde entre las nubes',false);lb.position.y=6.4;lb.visible=false;g.add(lb);addCirc(f[0],f[1],0.9);
    OLYM.gate={kind:'olygate',x:f[0],z:f[1],g,lb,data:{name:'Sendero del Olimpo',role:''}};}}
// ---- examen de una musa
function museTalk(o){const m=o.m,mz=muz(),done=mz.dons[m.id];dlg={n:null};ui='dialog';releasePointer();
  $('dGlyph').textContent=m.name.charAt(0);setName(m.name);$('dTitle').textContent='Musa de '+m.arte+' · hija de Zeus y de Mnemósine';
  const opt=$('dOpts');const one=(t,fn,c)=>{const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(opt.children.length+1)+'</span><span>'+t+'</span>';b.onclick=fn;opt.appendChild(b);};
  opt.innerHTML='';
  if(done){$('dBody').innerHTML='<p>Ya llevas mi don: '+m.don+'. Úsalo bien, mortal. Y cuando reúnas los de mis ocho hermanas, busca a nuestra madre, Mnemósine.</p><p class="sub">Dones reunidos: '+Object.keys(mz.dons).length+' de 9.</p>';one('Despedirse',closeDialog);$('dialog').hidden=false;return;}
  const learned=m.pre.filter(id=>state.lessons.includes(id)),names=m.pre.map(id=>{const n=NPCS.find(x=>x.id===id);return n?n.name:id;});
  $('dBody').innerHTML='<p>Soy '+m.name+', una de las nueve Musas. Inspiro '+m.arte+'. No regalo mi don a cualquiera: quien lo quiera tendrá que demostrar que sabe de lo mío. Y eso no se aprende de mí, sino de los hombres y mujeres que lo cultivan.</p>'+
    '<p class="sub">Para pedir el examen, aprende al menos dos lecciones de estas personas: '+names.map((nm,i)=>learned.includes(m.pre[i])?'<b>'+nm+' ✓</b>':nm).join(', ')+'. Llevas '+learned.length+'.</p>';
  if(learned.length<2){one('Iré a aprender',closeDialog);$('dialog').hidden=false;return;}
  if(mz.day[m.id]===state.day){$('dBody').innerHTML+='<p>«Ya me has respondido hoy. Vuelve mañana: las Musas no tenemos prisa».</p>';one('Despedirse',closeDialog);$('dialog').hidden=false;return;}
  one('Hacer el examen de '+m.name+' (4 preguntas, hay que acertar 3)',()=>museExam(o),'quiz');one('Todavía no',closeDialog);$('dialog').hidden=false;}
function museExam(o){const m=o.m,mz=muz();mz.day[m.id]=state.day;save();let i=0,ok=0;const opt=$('dOpts');
  const ask=()=>{const Q=m.q[i];$('dBody').innerHTML='<p class="sub">Pregunta '+(i+1)+' de '+m.q.length+'</p><p><b>'+Q[0]+'</b></p>';opt.innerHTML='';
    Q[1].map((t,k)=>[t,k===0]).sort(()=>R()-0.5).forEach(([t,good],k)=>{const b=document.createElement('button');b.className='quiz';b.innerHTML='<span class="n">'+(k+1)+'</span><span>'+t+'</span>';b.onclick=()=>{if(good)ok++;i++;if(i<m.q.length)ask();else end();};opt.appendChild(b);});};
  const end=()=>{opt.innerHTML='';const b=document.createElement('button');b.innerHTML='<span class="n">1</span><span>Despedirse</span>';b.onclick=closeDialog;
    if(ok>=3){mz.dons[m.id]=1;qAdd(m.dq,5,'El don de '+m.name+' te inspira.');qAdd('kl',2);sfxCoin();o.mk.visible=false;const n=Object.keys(mz.dons).length;
      $('dBody').innerHTML='<p>Has acertado '+ok+' de '+m.q.length+'. '+m.name+' sonríe y te toca la frente.</p><div class="curio"><span class="label">Don de '+m.name+'</span><p>Recibes '+m.don+'.</p></div><p class="sub">Dones reunidos: '+n+' de 9.'+(n>=9?' Ya los tienes todos: busca a Mnemósine, la madre de las Musas.':'')+'</p>';
      if(n>=9&&OLYM.mnemo)OLYM.mnemo.mk.visible=true;}
    else $('dBody').innerHTML='<p>Has acertado '+ok+' de '+m.q.length+'. «No es suficiente. Vuelve a escuchar a quienes saben y regresa mañana».</p>';
    save();updateStats();opt.appendChild(b);};
  ask();}
function mnemoTalk(){const n=Object.keys(muz().dons).length,ro=MODE==='roma';dlg={n:null};ui='dialog';releasePointer();
  $('dGlyph').textContent='Μ';setName('Mnemósine');$('dTitle').textContent='Titánide de la memoria · madre de las nueve Musas';const opt=$('dOpts');opt.innerHTML='';
  const one=(t,fn,c)=>{const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(opt.children.length+1)+'</span><span>'+t+'</span>';b.onclick=fn;opt.appendChild(b);};
  if(state.olyKey){$('dBody').innerHTML='<p>Ya recuerdas el camino. Sube por el '+(ro?'Capitolio, donde los romanos honran a Júpiter':'valle de Tesalia, al pie del Olimpo')+', hasta el sendero entre las nubes.</p>';one('Despedirse',closeDialog);}
  else if(n<9){$('dBody').innerHTML='<p>Soy la Memoria. Sin mí no habría cantos, ni historia, ni ciencia: todo se olvidaría. Mis nueve hijas reparten sus dones a quienes aprenden. Tú llevas '+n+' de 9.</p><p>Cuando los tengas todos, vuelve: te daré de beber de mi fuente, y recordarás un camino que los mortales olvidaron.</p>';one('Despedirse',closeDialog);}
  else{$('dBody').innerHTML='<p>Llevas los nueve dones. Mis hijas confían en ti. Bebe de mi fuente.</p><p>Al beber, recuerdas algo que nunca habías vivido: un sendero que sube desde '+(ro?'el Capitolio':'el valle de Tesalia')+' hasta las cumbres del Olimpo, donde viven los dioses.</p><p class="sub">En la Beocia, junto a los oráculos, se decía que había dos fuentes: la del Olvido y la de la Memoria. Los iniciados debían beber de la segunda.</p>';
    one('Beber del agua de la Memoria',()=>{state.olyKey=1;qAdd('so',5);qAdd('eu',5);save();updateStats();sfxCoin();OLYM.mnemo.mk.visible=false;closeDialog();toast('<span class="label">Agua de la Memoria</span><br>Ya recuerdas el sendero del Olimpo: búscalo '+(ro?'en el Capitolio, junto al templo de Júpiter':'en la llanura de Tesalia, cerca de Larisa')+'.');},'quiz');}
  $('dialog').hidden=false;}
// ---- el Olimpo: un palacio sobre las nubes
function buildOlympus(){if(OLYM.built)return;OLYM.built=true;const I=ISLANDS[0],X=I.x,Z=I.z+6200,Y=OLYM.y;Object.assign(OLYM,{x:X,z:Z});
  const g=grp(X,Y,Z,0),marble=lam('#f4efe4'),gold=lam('#e0b84a');
  const cl=new THREE.Mesh(new THREE.CircleGeometry(260,48),new THREE.MeshLambertMaterial({color:'#f6f8fb',transparent:true,opacity:0.95}));cl.rotation.x=-Math.PI/2;cl.position.y=-1.2;g.add(cl);
  for(let i=0;i<40;i++){const s=new THREE.Sprite(new THREE.SpriteMaterial({map:HALO_TEX,color:'#ffffff',transparent:true,opacity:0.55,depthWrite:false}));const a=R()*TAU,d=60+R()*190;s.position.set(Math.cos(a)*d,rr(-2,6),Math.sin(a)*d);s.scale.set(rr(20,40),rr(8,14),1);g.add(s);}
  box(90,2,110,marble,0,-1,0,g);addPlat(X,Z,90,110,0,Y);
  for(const[a,b,c,d]of[[-45,-55,45,-55],[45,-55,45,55],[45,55,-45,55],[-45,55,-45,-55]])addSeg(X+a,Z+b,X+c,Z+d,0.4);
  box(40,1.2,56,marble,0,0.6,-20,g);addPlat(X,Z-20,40,56,0,Y+1.2);
  for(let i=0;i<8;i++)for(const s of[-1,1]){const c=new THREE.Mesh(new THREE.CylinderGeometry(0.8,0.9,14,16),marble);c.position.set(s*17,8.2,-44+i*7.4);g.add(c);addCirc(X+s*17,Z-44+i*7.4,0.9);}
  box(40,2,58,marble,0,16,-20,g);box(42,0.6,60,gold,0,17.3,-20,g);
  const th=new THREE.Group();th.position.set(0,1.2,-42);g.add(th);box(4,1,3,gold,0,0.5,0,th);box(4,6,0.6,gold,0,3.5,-1.3,th);box(0.6,2,3,gold,-1.8,1.6,0,th);box(0.6,2,3,gold,1.8,1.6,0,th);
  for(let i=0;i<11;i++){const a=-1.2+i*0.24,tx=Math.sin(a)*16,tz=-30-Math.cos(a)*10;const t=new THREE.Group();t.position.set(tx,1.2,tz);t.rotation.y=-a;g.add(t);box(2,0.8,1.8,marble,0,0.4,0,t);box(2,3,0.4,marble,0,2,-0.8,t);}
  const ro=MODE==='roma',zx=X,zz=Z-38.5;const Zf=divineFigure(zx,zz,{chiton:'#fff4dc',himation:ro?'#7a1c3a':'#3a4a8a',beard:true,hair:'#d8d0c2',beardC:'#e8e0d0',attrs:['G_thunderbolt_hand']},'#fff0b0',ro?'Júpiter':'Zeus',ro?'Óptimo Máximo, padre de los dioses':'padre de dioses y hombres',1.8);
  Zf.g.rotation.y=0;Zf.g.position.y=OLYM.y+1.2;OLYM.zeus={kind:'zeus',x:zx,z:zz+2.5,g:Zf.g,lb:Zf.lb,mk:Zf.mk,data:{name:ro?'Júpiter':'Zeus',role:''}};Zf.mk.visible=!state.zeusMet;
  const bk=grp(X,Y,Z+48,0);box(1,3,1,marble,0,1.5,0,bk);const lb=labelSprite('Bajar del Olimpo','volver al mundo de los mortales',false);lb.position.y=4;lb.visible=false;bk.add(lb);OLYM.back={kind:'olyback',x:X,z:Z+48,g:bk,lb,data:{name:'Bajar del Olimpo',role:''}};}
function olyTravel(up){ui='voyage';if(MOUNT.riding)dismount();if(MOUNT.g){MOUNT.g.visible=false;MOUNT.st='away';}FLY.on=false;const v=$('voyage');v.classList.add('land');
  v.querySelector('.vt').textContent=up?'Subes por el sendero entre las nubes…':'Bajas del Olimpo…';v.querySelector('.vs').textContent=up?'El aire se vuelve dorado. Ya no se oyen las ciudades.':'Las nubes se abren y vuelves a ver la tierra de los mortales.';v.querySelector('.vf').textContent='';v.hidden=false;requestAnimationFrame(()=>v.classList.add('show'));
  setTimeout(()=>{if(up){buildOlympus();player.x=OLYM.x;player.z=OLYM.z+40;player.yaw=0;}else{const G=OLYM.gate;player.x=G.x+3;player.z=G.z+3;}
    player.feet=floorAt(player.x,player.z);player.camY=player.feet+player.eye;player.vy=0;player.pitch=0;curZone=null;v.classList.remove('show');setTimeout(()=>{v.hidden=true;ui='play';if(up)toast('<span class="label">El Olimpo</span><br>Al fondo del palacio, en su trono, te espera '+(MODE==='roma'?'Júpiter':'Zeus')+'.');},700);},2600);}
function olyGateTalk(){dlg={n:null};ui='dialog';releasePointer();$('dGlyph').textContent='Ο';setName('Sendero del Olimpo');$('dTitle').textContent='Un camino que se pierde entre las nubes';const opt=$('dOpts');opt.innerHTML='';
  const one=(t,fn,c)=>{const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(opt.children.length+1)+'</span><span>'+t+'</span>';b.onclick=fn;opt.appendChild(b);};
  if(!state.olyKey){$('dBody').innerHTML='<p>Un sendero de piedra blanca sube hacia las nubes y se borra. Por más que lo intentas, no recuerdas por dónde sigue. Los mortales olvidaron hace mucho el camino de los dioses.</p><p class="sub">Quizá la Memoria pueda ayudarte. Dicen que solo atiende a quien ha reunido los dones de sus nueve hijas, las Musas.</p>';one('Volver',closeDialog);}
  else{$('dBody').innerHTML='<p>Ahora recuerdas el sendero. Cada piedra está donde la memoria dice que debe estar.</p>';one('Subir al Olimpo',()=>{closeDialog();olyTravel(true);},'quiz');one('Ahora no',closeDialog);}
  $('dialog').hidden=false;}
function zeusTalk(){const ro=MODE==='roma',Z=ro?'Júpiter':'Zeus';dlg={n:null};ui='dialog';releasePointer();$('dGlyph').textContent=Z.charAt(0);setName(Z);$('dTitle').textContent=ro?'Júpiter Óptimo Máximo · padre de los dioses':'Zeus Olímpico · padre de dioses y hombres';
  const opt=$('dOpts');const T=ro?[
   ['¿Por qué te llaman Óptimo Máximo?','Porque soy el mejor y el más grande, y Roma me lo recuerda en cada triunfo: el general vencedor sube al Capitolio vestido como yo, con la cara pintada de rojo, y un esclavo le susurra al oído que es mortal. Este año mi templo del Capitolio ha ardido. No te preocupes: no vivo en él. Vivo aquí, y en cada juramento que los romanos cumplen.'],
   ['¿Qué esperas de los romanos?','Fides: que cumplan su palabra. Los tratados, los contratos, los juramentos se hacen ante mí. Cuando un romano jura por Júpiter y miente, el rayo es lo de menos: lo peor es que ya nadie confía en él.'],
   ['¿Eres el mismo que el Zeus de los griegos?','Los romanos me reconocieron en él cuando conocieron a los griegos. Pero yo era Júpiter antes: el dios del cielo de los latinos, el del rayo y la lluvia, el que veneraban los pastores del Lacio. Los nombres cambian; el cielo es el mismo.']]:[
   ['¿Cómo llegaste a reinar?','Mi padre Crono devoraba a sus hijos para que ninguno lo destronara. Mi madre Rea me escondió en Creta y le dio a él una piedra envuelta en pañales. Crecí, le hice vomitar a mis hermanos y luchamos diez años contra los Titanes. Vencimos, y repartimos el mundo: a Poseidón el mar, a Hades el mundo de abajo, a mí el cielo.'],
   ['¿Qué esperas de los hombres?','Que respeten a los huéspedes, a los suplicantes y los juramentos. Soy Zeus Xenio, protector de los forasteros: quien cierra la puerta a un viajero me la cierra a mí. Y le di a los hombres la justicia, Dike, para que no vivieran como los peces, que se comen unos a otros.'],
   ['¿Por qué no se te encuentra por los caminos?','Porque soy el padre, no un vecino. Mis hijos y mis hermanos bajan a la tierra con más gusto. A mí solo llegan quienes han aprendido de verdad: por eso te pedí, a través de mis hijas y de su madre, que recordaras antes de subir.']];
  const menu=()=>{opt.innerHTML='';let k=1;const add=(t,fn,c)=>{const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(k++)+'</span><span>'+t+'</span>';b.onclick=fn;opt.appendChild(b);};
    T.forEach(t=>add(t[0],()=>{$('dBody').innerHTML='<p>'+t[1]+'</p>';menu();}));
    if(!state.zeusMet)add('Recibir la bendición de '+Z,()=>{state.zeusMet=1;['so','lo','ar','eu','kl'].forEach(q=>qAdd(q,6));state.obols+=20;save();updateStats();sfxCoin();OLYM.zeus.mk.visible=false;
      $('dBody').innerHTML='<p>'+Z+' levanta la mano y el cielo retumba sin una nube. «Has aprendido de los hombres, has convencido a mis hijas y has recordado lo que todos olvidaron. Vuelve abajo y enseña lo que sabes: así es como los mortales se acercan a los dioses».</p><div class="curio"><span class="label">Bendición de '+Z+'</span><p>Todas tus cualidades crecen, y recibes veinte '+(ro?'sestercios':'óbolos')+' de oro del tesoro de los dioses.</p></div>';menu();},'quiz');
    add('Despedirse',closeDialog);};
  $('dBody').innerHTML='<p>'+(ro?'Así que tú eres el mortal que ha convencido a las nueve Musas. Pocos llegan hasta aquí. Siéntate… no, ahí no: ese es el trono de Juno.':'Así que tú eres el mortal que ha convencido a mis nueve hijas y ha bebido de la Memoria. Pocos llegan hasta aquí. Siéntate… no, ahí no: ese es el trono de Hera.')+'</p>';menu();$('dialog').hidden=false;}
function musesHTML(){const mz=muz(),L=MUSAS();return '<h3 style="margin:22px 0 10px">Las nueve Musas</h3><p style="margin:0 0 12px;max-width:68ch;line-height:1.5">Cada Musa espera en el lugar que mejor conviene a su arte. Aprende de las personas que lo cultivan, supera su examen y recibe su don. Con los nueve, busca a Mnemósine'+(state.olyKey?' (ya bebiste de su fuente: sube al Olimpo)':'')+'.</p><div class="entries">'+
  L.map(m=>{const ok=mz.dons[m.id];const p=PLACES.find(q=>'place:'+q.id===m.at);return '<div class="entry'+(ok?'':' locked')+'"><span class="label">'+(ok?'Don recibido ✓':'Musa de '+m.arte)+'</span><h3>'+m.name+'</h3><p>'+(ok?'Te dio '+m.don+'.':'Inspira '+m.arte+'.')+'</p><div class="where">'+(p?'Cerca de: '+p.name:'')+'</div></div>';}).join('')+'</div>';}

// ---- calendario y estaciones: cada cinco días de juego pasa un mes, cada tres meses cambia la estación (empieza en abril)
const SEASON_DAYS=5;
const SEASONS=[{id:'pri',n:'primavera',fol:'#ffffff',ter:'#e2c99e'},{id:'ver',n:'verano',fol:'#f2dc96',ter:'#f2cf92'},{id:'oto',n:'otoño',fol:'#e8a060',ter:'#d4b48a'},{id:'inv',n:'invierno',fol:'#a4b2a6',ter:'#c4c4a6'}];   // en invierno llueve: el campo reverdece
const MESES_A=['Gamelión','Antesterión','Elafebolión','Muniquión','Targelión','Esciroforión','Hecatombeón','Metagitnión','Boedromión','Pianepsión','Memacterión','Posideón'];
const MESES_R=['Ianuarius','Februarius','Martius','Aprilis','Maius','Iunius','Iulius','Augustus','September','October','November','December'];
function calNow(d){d=d||(state&&state.day)||1;const m=3+Math.floor((d-1)/SEASON_DAYS),mo=m%12,ro=MODE==='roma';
  return {mo,mes:(ro?MESES_R:MESES_A)[mo],season:SEASONS[Math.floor(((mo+10)%12)/3)],year:ro?80+Math.floor(m/12):386-Math.floor(m/12)};}
function regionName(){{const fz=fzIn();if(fz)return fz==='race'?(MODE==='roma'?'Un trigal del Lacio':'El estadio'):fz==='tel'?'Eleusis':player.z-6000>155?'Los Campos Elíseos':'Los Infiernos';}if(cavIn())return MODE==='roma'?'El Sueño de Escipión':player.z-CAV.Z<95?'La caverna':player.feet<CAV.Y+50?'Fuera de la caverna':'El mundo de las Ideas';if(player.feet>MOON.y-50)return 'La Luna';if(player.feet>CASA.Y-50)return 'Tu casa';if(OLYM.built&&player.feet>OLYM.y-50)return 'El Olimpo';const I=islandOf(player.x);return I?I.name:(MODE==='roma'?'Roma':'Atenas');}
let hudKey='';
function hudTitleTick(){if(!state)return;const c=calNow(),k=regionName()+'|'+c.season.id+'|'+c.year+'|'+!!storyHud;if(k===hudKey)return;hudKey=k;
  $('hudTitle').textContent=(qLv('kl')>=2&&pjz()&&pjz().name?pjz().name+' · ':'')+regionName()+' · '+c.season.n+' del '+(MODE==='roma'?'año '+c.year+' d.C.':c.year+' a.C.')+(storyHud?' · Historia':'');applySeason(c.season);hudPeek(7);}
// el cartel de arriba a la izquierda aparece unos segundos al cambiar de ciudad o de estación y luego se recoge hacia arriba (menos ruido en pantalla);
// también asoma si llevas el ratón a esa esquina
let HUDP_T=null;function hudPeek(s){const e=$('stats');if(!e)return;e.classList.remove('hid');e.classList.add('show');clearTimeout(HUDP_T);HUDP_T=setTimeout(()=>{e.classList.remove('show');e.classList.add('hid');},(s||6)*1000);}
addEventListener('mousemove',ev=>{const e=$('stats');if(!e||!e.classList.contains('hid')||document.pointerLockElement)return;if(ev.clientX<360&&ev.clientY<140)hudPeek(4);});
let storyHud=false,seasonOn=null;const TERR_MATS=[];
function applySeason(s){if(seasonOn===s.id)return;seasonOn=s.id;const f=new THREE.Color(s.fol);
  ['foliage','vine'].forEach(r=>{if(WHITE_ROLE[r])WHITE_ROLE[r].color.copy(f);if(ROLE_MAT[r])ROLE_MAT[r].color.set(ROLE_C[r]).multiply(f);});
  TERR_MATS.forEach(m=>m.color.set(s.ter));cropSeason(s.id);}
// la primera vez que cambia la estación, alguien te explica quiénes son las Horas
const HORAS={
 A:{who:'Filis',t:'Vendedora de flores del Ágora',g:'Ω',
  intro:'«¿Lo notas? Ha cambiado el aire. Han pasado por aquí las Horas». Una mujer con un cesto de flores y espigas se para a tu lado. «Soy Filis. Vendo coronas para los sacrificios, así que vivo pendiente de ellas: sin las Horas no tendría nada que vender».',
  topics:[['¿Quiénes son las Horas?','Las hijas de Zeus y de Temis, la diosa del orden justo. Hesíodo dice que son tres: Eunomía, el buen gobierno; Dike, la justicia; y Eirene, la paz. Cuidan de que todo llegue a su tiempo: las cosechas en la tierra y las leyes en la ciudad. Si las cosas pasan cuando deben pasar, es que las Horas están contentas.'],
   ['¿Y aquí, en Atenas?','Aquí honramos a dos: Talo, la que hace brotar, y Carpo, la que hace madurar el fruto. Les ofrecemos la carne hervida, no asada, para pedirles que el calor no queme las cosechas y que llueva a su tiempo. Pausanias, que no ha nacido aún, lo apuntará cuando visite la ciudad.'],
   ['¿Qué hacen en los mitos?','Homero cuenta que guardan las puertas del cielo: abren y cierran la nube espesa que hay en la entrada del Olimpo, para dejar pasar los carros de los dioses. Cuando nació Afrodita del mar, fueron ellas las que la vistieron y la coronaron de oro. Y a Pandora, la primera mujer, la adornaron con flores de primavera.'],
   ['¿Por qué cambian las estaciones?','Por Perséfone, la hija de Deméter. Hades se la llevó al mundo de los muertos, y su madre, de pena, dejó la tierra sin cosechas. Al final se pactó que la muchacha pasaría una parte del año abajo y otra con su madre. Cuando sube, las Horas traen la primavera; cuando baja, llega el frío.'],
   ['¿Cuántas estaciones hay?','Los campesinos hablamos de tres o de cuatro: la primavera; el verano, la siega; el otoño, la vendimia; y el invierno, cuando el mar se cierra y se poda. Los poetas cuentan las Horas de muchas maneras: dos, tres, cuatro… Pero el orden es siempre el mismo, y nadie se lo salta. Ni Zeus.']],
  src:'Hesíodo, Teogonía 901-903 y Trabajos y días 73-75; Ilíada V 749-751; Himno homérico VI a Afrodita; Ateneo XIV 656a (Filócoro); Pausanias IX 35.2'},
 R:{who:'Aulo',t:'Pintor de frescos',g:'A',
  intro:'Un hombre con las manos manchadas de colores se aparta de una pared a medio pintar. «Ha cambiado la estación, ¿eh? Justo a tiempo: me han encargado las cuatro Estaciones para un comedor. Soy Aulo, pintor. Mira, te explico a quién estoy pintando».',
  topics:[['¿Quiénes son las Horas?','Para los griegos, las Horas son las hijas de Júpiter y de Temis, guardianas del orden del mundo: que cada cosa llegue a su tiempo. Nosotros también las llamamos Horas, y en las casas de los ricos las pintamos como cuatro muchachas o cuatro niños: la Primavera con flores, el Verano con espigas, el Otoño con uvas y el Invierno abrigado, con una rama seca o un pato.'],
   ['¿Por qué cuatro?','Porque el año romano se divide así para el campo, y porque son cuatro también las edades del hombre: niñez, juventud, madurez y vejez. Ovidio, en las Metamorfosis, pone a las cuatro alrededor del trono del Sol: la Primavera coronada de flores, el Verano desnudo con espigas, el Otoño manchado de uva pisada y el Invierno con el pelo blanco y erizado.'],
   ['¿Y en los mitos?','Homero dice que vigilan las puertas del cielo y abren o cierran la nube que las tapa. Y cuando Proserpina (los griegos dicen Perséfone) fue raptada por Plutón, su madre Ceres dejó la tierra estéril. Desde entonces la hija pasa una parte del año abajo: por eso hay invierno.'],
   ['¿Qué dicen los poetas?','Horacio tiene una oda muy triste y muy bonita: la nieve se va, vuelve la hierba, el verano empuja a la primavera y el invierno vuelve a todo correr. Las estaciones se recuperan, dice, pero nosotros, cuando bajamos con los muertos, ya no. Por eso hay que aprovechar el día. Yo lo aprovecho pintando. Y cobrando.']],
  src:'Hesíodo, Teogonía 901-903; Ilíada V 749-751; Ovidio, Metamorfosis II 25-30 y V 385-571; Horacio, Odas IV 7'}};
function horasTalk(){const H=HORAS[MODE==='roma'?'R':'A'],seen=new Set();dlg={n:null};ui='dialog';releasePointer();
  $('dGlyph').textContent=H.g;setName(H.who,true);$('dTitle').textContent=H.t+' · las Horas';const opt=$('dOpts');
  const render=()=>{opt.innerHTML='';H.topics.forEach(([q,a],i)=>{const b=document.createElement('button');if(seen.has(i))b.className='seen';b.innerHTML='<span class="n">'+(i+1)+'</span><span>'+q+'</span>';
    b.onclick=()=>{seen.add(i);if(seen.size===H.topics.length&&!state.horas.done){state.horas.done=1;qAdd('eu',3);qAdd('so',2);save();updateStats();sfxCoin();}$('dBody').innerHTML='<p>'+a+'</p>'+(seen.size===H.topics.length?'<p class="sub">Fuentes: '+H.src+'.</p>':'');render();};opt.appendChild(b);});
    const b=document.createElement('button');b.innerHTML='<span class="n">'+(H.topics.length+1)+'</span><span>Despedirse</span>';b.onclick=closeDialog;opt.appendChild(b);};
  $('dBody').innerHTML='<p>'+H.intro+'</p>';render();$('dialog').hidden=false;}
let seasonT=0;
function seasonTick(dt){hudTitleTick();const nw=performance.now();if(nw-seasonT<1000||!state)return;seasonT=nw;const c=calNow();
  if(!state.horas)state.horas={s:c.season.id};
  if(state.horas.s!==c.season.id){state.horas.s=c.season.id;state.horas.pend=1;save();toast('<span class="label">Llega el '+c.season.n+'</span><br>Empieza el mes de '+c.mes+'. Los campos y los árboles cambian de color.');}
  if(state.horas.pend&&ui==='play'&&!state.horas.met){state.horas.pend=0;state.horas.met=1;save();setTimeout(()=>{if(ui==='play')horasTalk();else state.horas.pend=1;},2500);}}
// ---- casa propia: un forastero no puede tener casa sin un permiso especial (Atenas: énktesis por decreto; Roma: ciudadanía del emperador)
