function casaTravel(inn){ui='voyage';if(MOUNT.riding)dismount();if(MOUNT.g){MOUNT.g.visible=false;MOUNT.st='away';}FLY.on=false;
  const v=$('voyage');v.classList.add('land');v.querySelector('.vt').textContent=inn?'Abres la puerta de tu casa…':'Sales a la calle…';v.querySelector('.vs').textContent='';v.querySelector('.vf').textContent='';v.hidden=false;requestAnimationFrame(()=>v.classList.add('show'));
  setTimeout(()=>{CASA.inside=inn;if(inn){player.x=CASA.X;player.z=CASA.Z+12.5;player.yaw=0;}else{const D=CASA.door;player.x=D.x;player.z=D.z+1.5;player.yaw=Math.PI;}
    player.feet=floorAt(player.x,player.z);player.camY=player.feet+player.eye;player.vy=0;player.pitch=0;curZone=null;hudKey='';v.classList.remove('show');setTimeout(()=>{v.hidden=true;ui='play';},600);},1400);}
function casaOpen(glyph,name,title){dlg={n:null};ui='dialog';releasePointer();$('dGlyph').textContent=glyph;setName(name,true);$('dTitle').textContent=title;const opt=$('dOpts');opt.innerHTML='';
  return (t,fn,c)=>{const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(opt.children.length+1)+'</span><span>'+t+'</span>';b.onclick=fn;opt.appendChild(b);};}
function casaAgentTalk(){const ro=MODE==='roma',c=cz(),mon=ro?'sestercios':'óbolos',fr=bestFriend(),wait=CASA.espera[ro?'R':'A'],fxm=ro||fxz().st==='meteco';if(ro&&fxz().ciu&&c.st<2){c.st=2;c.fr=c.fr||'derecho latino';save();}
  const one=casaOpen(ro?'A':'Φ',ro?'Sexto Afranio':'Formión',ro?'Argentario: cambio, préstamos y compraventa':'Esclavo de confianza de Pasión, el banquero');const B=$('dBody'),back=()=>casaAgentTalk();
  if(c.st>=3){B.innerHTML='<p>'+(ro?'«¡Salve, ciudadano! ¿Qué tal la casa? Si algún día quieres venderla, ya sabes dónde estoy. Aunque nadie vende una casa así en Roma, con lo que cuestan».':'«¿Qué tal la casa? Pasión dice que eres el primer forastero que ve llegar con las manos vacías y acabar con casa propia. Bueno, él también llegó así».')+'</p>';one('Despedirse',closeDialog);$('dialog').hidden=false;return;}
  if(c.st===0){B.innerHTML=ro?'<p>«¿Una casa? ¿Tú? Mira, amigo, en Roma un peregrino, un extranjero sin ciudadanía, no puede ser dueño de suelo romano según el derecho de los Quirites. Puedes alquilar un piso en una ínsula, como medio Roma. Pero ¿comprar? Para eso tienes que ser ciudadano».</p><p>«Y la ciudadanía, a alguien como tú, solo la da el emperador. Se la pide un patrono, alguien importante que responda por ti. Así se hace siempre: un senador la pide para su médico griego, o un general para un soldado valiente. Y luego están los escribas de la cancillería imperial, que no escriben gratis».</p>':
     '<p>«¿Comprar una casa? Eres meteco, amigo, un extranjero residente. Los metecos no pueden tener casa ni tierra en el Ática. Pagas tu impuesto, el metoíkion, y vives de alquiler. Así es la ley».</p><p>«Salvo que la Asamblea vote un decreto que te dé la énktesis, el derecho a tener casa y tierra. Se concede a quien hace un gran servicio a la ciudad. Mi amo Pasión ha regalado escudos y dinero a Atenas, y ahora se habla de hacerlo ciudadano. Necesitas un ciudadano que proponga el decreto y una donación, una epídosis, para las murallas que Conón ha reconstruido».</p>';
    B.innerHTML+='<p class="sub">Necesitas: '+(ro?'':(fxm?'✓ ':'✗ ')+'estar inscrito como meteco (habla con el demarco de Mélite) · ')+(fr?'✓ ':'✗ ')+'un amigo importante con al menos «Confianza»'+(fr?' ('+fr.name+')':'')+' · '+(state.obols>=CASA.don?'✓ ':'✗ ')+CASA.don+' '+mon+' para '+(ro?'los escribas':'la donación')+' · luego, '+CASA.precio+' '+mon+' por la casa.</p>';
    if(fxm&&fr&&state.obols>=CASA.don)one(ro?'Pedir a '+fr.name+' que te recomiende al emperador ('+CASA.don+' '+mon+')':'Pedir a '+fr.name+' que proponga el decreto y donar '+CASA.don+' '+mon,()=>{state.obols-=CASA.don;c.st=1;c.day=state.day||1;c.fr=fr.name;qAdd('kl',3);save();updateStats();sfxCoin();
      B.innerHTML=ro?'<p>'+fr.name+' escribe una carta al emperador Tito: «Te ruego, señor, que concedas la ciudadanía romana a este amigo mío, persona honrada y de buenas costumbres…». Sexto Afranio paga a los escribas y sella la petición.</p><p>«Ahora, a esperar. La respuesta del emperador tarda unos '+wait+' días. Vuelve entonces».</p>':'<p>'+fr.name+' acepta proponer el decreto en la Asamblea. Entregas tu donación al tesorero: tu nombre se grabará en la lista de los que han ayudado a la ciudad.</p><p>«La Asamblea votará dentro de unos '+wait+' días. Si sale bien, el decreto se grabará en una estela. Vuelve entonces».</p>';one('Despedirse',closeDialog);});
    one('Despedirse',closeDialog);$('dialog').hidden=false;return;}
  if(c.st===1){const left=c.day+wait-(state.day||1);if(left>0){B.innerHTML='<p>«Todavía no hay respuesta. Vuelve dentro de '+left+' día'+(left>1?'s':'')+'».</p>';one('Despedirse',closeDialog);$('dialog').hidden=false;return;}
    c.st=2;if(ro){fxz().ciu=true;fxz().via=fxz().via||'emperador';pjAvatar();}save();B.innerHTML=ro?'<p>«¡Ha llegado la respuesta del emperador! Mira: “El emperador Tito César Vespasiano Augusto concede la ciudadanía romana a…”. ¡Eres ciudadano romano!».</p><p>«Como todos los que reciben la ciudadanía del emperador, tomas su nombre de familia: desde hoy eres un Flavio, y tu nombre de siempre queda como apodo. Ahora sí puedes comprar suelo romano. Tengo una casita en el Quirinal, con atrio y todo, por '+CASA.precio+' sestercios. Una ganga: en Roma, hasta un cuchitril cuesta una fortuna».</p>':'<p>«¡Buenas noticias! La Asamblea ha votado el decreto que propuso '+c.fr+': “Que se le conceda la énktesis de tierra y casa, por su buena disposición hacia el pueblo de los atenienses”. Lo grabarán en una estela en la Acrópolis».</p><p>«Sigues siendo meteco, pero ya puedes tener casa. Tengo una en Melite, al lado del Ágora: con patio, almacén, andrón y todo. '+CASA.precio+' óbolos. Una ganga: las casas buenas cuestan minas enteras».</p>';
    qAdd('kl',5);updateStats();}
  else B.innerHTML='<p>'+(ro?'«Ya eres ciudadano. La casa del Quirinal sigue esperándote: ':'«Ya tienes el decreto. La casa de Melite sigue esperándote: ')+CASA.precio+' '+mon+'».</p>';
  if(state.obols>=CASA.precio)one('Comprar la casa ('+CASA.precio+' '+mon+')',()=>{state.obols-=CASA.precio;c.st=3;save();updateStats();sfxCoin();CASA.agent.mk.visible=false;
    const D=CASA.door,nl=labelSprite('Tu casa','entrar',false);nl.position.y=4.1;nl.visible=false;D.g.remove(D.lb);D.g.add(nl);D.lb=nl;
    B.innerHTML='<p>'+(ro?'Sexto Afranio redacta el contrato en unas tablillas de cera, ante siete testigos, y te da la llave de hierro. ':'Formión anota la venta y te entrega la llave, una gran llave de bronce. ')+'La puerta está aquí mismo, a unos pasos. Ya tienes un hogar en '+(ro?'Roma':'Atenas')+'.</p>';one('Despedirse',closeDialog);},'quiz');
  else one('Volveré con el dinero (te faltan '+(CASA.precio-state.obols)+' '+mon+')',closeDialog);
  one('Despedirse',closeDialog);$('dialog').hidden=false;}
function casaDoor(){if(cz().st>=3){casaTravel(true);return;}const one=casaOpen('⌂','Casa en venta','Una puerta cerrada con un cartel');
  $('dBody').innerHTML='<p>En la puerta hay un cartel: «Se vende. Preguntad a '+(MODE==='roma'?'Sexto Afranio, el argentario':'Formión, en la mesa de Pasión')+'». Está aquí mismo, al lado.</p>';one('Volver',closeDialog);$('dialog').hidden=false;}
const CASA_COMIDA={A:['Hoy comes como casi todos los atenienses: maza, una torta de cebada, con aceitunas, queso, higos secos y cebolla. El pan de trigo es para los días buenos. Se bebe vino mezclado con agua.','Hay pescado: unas sardinas fritas del Falero. La carne se come casi solo en las fiestas, cuando se sacrifica un animal y se reparte entre todos.','Lentejas con aceite y hierbas, y de postre, miel del Himeto. Los griegos se ríen de los bárbaros que beben el vino sin agua.'],
 R:['Hoy toca puls, unas gachas de trigo, con verduras, huevos y un poco de queso. Como los antiguos romanos, dice la cocinera, «que conquistaron el mundo comiendo gachas».','Pan, aceitunas, higos y un pescado con garum, la salsa de pescado fermentado que lo condimenta todo. Huele fuerte, pero a todo el mundo le encanta.','Para cenar: huevos, lechuga, un poco de cerdo y fruta. «Del huevo a las manzanas», dicen los romanos: así es una cena entera, del primer plato al postre.']};
function hogarAct(o){const ro=MODE==='roma',c=cz(),d=state.day||1,mon=ro?'sestercios':'óbolos';if(o.act==='salir'){casaTravel(false);return;}if(ro&&o.act==='altar'){cultoAct({ctx:'casa',data:{name:'Tu larario'}});return;}
  const one=casaOpen('⌂',o.data.name,ro?'Tu casa en el Quirinal':'Tu casa en Melite');const B=$('dBody');
  if(o.act==='dormir'){B.innerHTML='<p>'+(ro?'El cubículo es pequeño y sin ventana, como todos: solo para dormir. ':'Una cama de madera con un colchón de lana y una manta. ')+'¿Duermes hasta el alba?</p>';
    one('Dormir',()=>{const h=clock.h,dh=h>=6?24-h+6.5:6.5-h;closeDialog();addHours(dh);updateSky&&updateSky();toast('<span class="label">Buenos días</span><br>Has dormido en tu casa. '+(ro?'Fuera, Roma ya hace ruido: los carros que de noche no paran y los panaderos que gritan.':'Fuera, los gallos y los vendedores ya anuncian el día.'));save();},'quiz');}
  else if(o.act==='altar'){B.innerHTML=ro?'<p>El larario es el altar de la casa: dentro están los Lares, los dioses que protegen la familia, y el Genio del dueño. Cada día se les ofrece un poco de comida, vino o incienso; en las fiestas, una guirnalda.</p>':'<p>En el patio está el altar de Zeus Herkeios, «el del cercado», que protege la casa. En el interior, el hogar es de Hestia: con ella empieza y termina cada comida y cada sacrificio. Una casa sin hogar no es una casa.</p>';
    if(c.ofr!==d)one(ro?'Ofrecer incienso y vino a los Lares':'Hacer una libación a Zeus Herkeios y a Hestia',()=>{c.ofr=d;qAdd('eu',1);save();updateStats();B.innerHTML='<p>'+(ro?'Quemas incienso y viertes unas gotas de vino. Los Lares sonríen, o eso parece.':'Viertes un poco de vino sobre el altar y echas unos granos de incienso al fuego. La casa queda en paz.')+'</p><p class="sub">+1 '+qName(QUAL.find(q=>q.k==='eu'))+'</p>';$('dOpts').innerHTML='';one('Volver',closeDialog);},'quiz');
    else B.innerHTML+='<p class="sub">Hoy ya has hecho la ofrenda.</p>';}
  else if(o.act==='comer'){const L=CASA_COMIDA[ro?'R':'A'];B.innerHTML=ro?'<p>La cocina es un rincón con un fogón de obra y un horno pequeño. En muchas ínsulas no hay cocina: la gente come en las tabernas. Tú tienes suerte.</p>':'<p>Se cocina en braseros portátiles o en un fogón de obra. El humo sale por un agujero del tejado.</p>';
    if(c.comer!==d)one('Comer',()=>{c.comer=d;save();B.innerHTML='<p>'+L[d%L.length]+'</p>';$('dOpts').innerHTML='';one('Volver',closeDialog);},'quiz');else B.innerHTML+='<p class="sub">Ya has comido hoy. '+L[d%L.length]+'</p>';}
  else if(o.act==='despensa')B.innerHTML=ro?'<p>Ánforas de aceite de la Bética, vino de Campania, garum, trigo y legumbres. El agua no hace falta guardarla: llega por los acueductos a las fuentes de la calle, y los más ricos la tienen en casa con una tubería de plomo, pagando.</p>':'<p>Tinajas de aceite, ánforas de vino, cebada, higos secos y legumbres. En el Ática casi no se cultiva trigo: llega por mar desde el mar Negro y Egipto. Por eso a Atenas le importa tanto la flota.</p>';
  else if(o.act==='trabajo')B.innerHTML=ro?'<p>Una mesa con tablillas de cera, un estilo, papiro y tinta. Un romano de bien escribe cartas a diario: Cicerón escribía varias al día. Aquí puedes llevar tus cuentas y, quién sabe, un diario.</p><p class="sub">'+cnt(state.lessons)+' lecciones anotadas en tus tablillas.</p>':'<p>Un telar vertical, con los hilos tensados por pesas de barro. Hilar y tejer era el trabajo de las mujeres de la casa, esclavas incluidas: toda la ropa de la familia salía de aquí. Cada cuatro años, unas muchachas tejen el peplo nuevo de Atenea para las Panateneas.</p>';
  else if(o.act==='recuerdos'){const L=[cnt(state.lessons)+' lecciones aprendidas',cnt(state.places)+' lugares visitados',cnt((state.musas||{}).dons)+' dones de las Musas'];if(typeof hz==='function'&&hz().own)L.push('Tu caballo: '+(hz().name||'sin nombre'));if(state.zeusMet)L.push((ro?'Has hablado con Júpiter':'Has hablado con Zeus')+' en el Olimpo');const fs=Object.values(state.fest||{}).filter(Boolean).length;if(fs)L.push(fs+' fiestas celebradas');
    B.innerHTML='<p>En las estanterías vas guardando recuerdos de tus viajes: una tablilla, una figurilla, una moneda extranjera…</p><ul>'+L.map(x=>'<li>'+x+'</li>').join('')+'</ul>';}
  else if(o.act==='banquete'){const fr=bestFriend(),cost=20;B.innerHTML=ro?'<p>El triclinio tiene tres lechos alrededor de una mesa: caben nueve comensales, tres por lecho, recostados sobre el codo izquierdo. El anfitrión ocupa el lecho del medio.</p>':'<p>El andrón es la sala de los hombres. Aquí se celebra el simposio: después de cenar, recostados en los lechos, los invitados beben vino mezclado con agua, cantan, juegan al cótabo y conversan. Las mujeres de la familia no asisten.</p>';
    if(!ro&&pjFem())B.innerHTML+='<p class="sub">En Atenas, una mujer no se recostaría en el simposio de su casa: lo presidiría un pariente varón, y ella recibiría a sus amigas en las habitaciones de las mujeres. El juego te deja organizarlo igualmente.</p>';
    if(c.banq===d)B.innerHTML+='<p class="sub">Hoy ya has dado un banquete.</p>';
    else if(state.obols>=cost)one((ro?'Dar una cena':'Celebrar un simposio')+(fr?' e invitar a '+fr.name:'')+' ('+cost+' '+mon+')',()=>{state.obols-=cost;c.banq=d;qAdd('kl',2);qAdd('lo',1);if(fr){const f=fz(fr.id);f.p=Math.min(100,f.p+3);}save();updateStats();sfxCoin();
      B.innerHTML='<p>'+(ro?'Los invitados llegan con sus servilletas (se llevan las sobras envueltas en ellas, es la costumbre). Hay mimos, un lector de poesía y mucha conversación.':'Se elige un rey del banquete, que decide cuánta agua lleva el vino. Hay una flautista, canciones y una larga discusión sobre si es mejor ser justo o parecerlo.')+(fr?' '+fr.name+' se va contento.':'')+'</p>';$('dOpts').innerHTML='';one('Volver',closeDialog);},'quiz');
    else B.innerHTML+='<p class="sub">Un banquete cuesta '+cost+' '+mon+'.</p>';}
  one('Volver',closeDialog);$('dialog').hidden=false;}
