function profeDests(){const L=[],ro=MODE==='roma';L.push({t:'Región',n:ro?'Roma (el Foro)':'Atenas (el Ágora)',go:()=>[ro?40:0,ro?-8:0]});
  for(const I of ISLANDS){const P=PORTS[I.id+'_n']||PORTS[I.id];L.push({t:'Región',n:I.name,go:()=>P?[P.x,P.z]:[I.x,I.z]});}
  for(const s of signObjs)L.push({t:'Lugar',n:s.data.name,go:()=>[s.x,s.z]});
  for(const o of npcObjs)if(o.data&&o.data.name)L.push({t:'Persona',n:o.data.name+(o.data.title?' · '+o.data.title:''),go:()=>[o.x,o.z]});
  for(const o of MUSE_OBJS)L.push({t:'Musa',n:o.data.name,go:()=>[o.x,o.z]});
  if(OLYM.mnemo)L.push({t:'Musa',n:'Mnemósine',go:()=>[OLYM.mnemo.x,OLYM.mnemo.z]});if(OLYM.gate)L.push({t:'Lugar',n:'Sendero del Olimpo',go:()=>[OLYM.gate.x,OLYM.gate.z]});
  L.push({t:'Especial',n:'El Olimpo: palacio de '+(ro?'Júpiter':'Zeus'),go:()=>{buildOlympus();return[OLYM.x,OLYM.z+40,0];}});
  L.push({t:'Especial',n:'Interior de tu casa',go:()=>[CASA.X,CASA.Z+12.5,0]});
  if(BARCO.wright)L.push({t:'Persona',n:BARCO.wright.data.name+' · tu barco',go:()=>[BARCO.wright.x,BARCO.wright.z]});
  L.push({t:'Especial',n:'La Luna de Luciano',go:()=>{buildMoon();return[MOON.x,MOON.z+36,0];}});
  if(TOUR.obj)L.push({t:'Persona',n:TOUR.obj.data.name+' · ruta de '+tourDef().poem,go:()=>[TOUR.x,TOUR.z]});
  if(CASA.agent)L.push({t:'Persona',n:CASA.agent.data.name+' · casas',go:()=>[CASA.agent.x,CASA.agent.z]});
  for(const c of CARTERS||[])if(c.data&&c.x!==undefined)L.push({t:'Persona',n:c.data.name+' · carretero',go:()=>[c.x,c.z]});
  return L;}
function profeGo(d){const r=d.go();let x=r[0],z=r[1];if(r[2]===undefined){const f=findFree(x+2,z+2,0.5);x=f[0];z=f[1];}
  if(MOUNT.riding)dismount();if(MOUNT.g){MOUNT.g.visible=false;MOUNT.st='away';}FLY.on=false;
  player.x=x;player.z=z;player.feet=floorAt(x,z);player.camY=player.feet+player.eye;player.vy=0;player.pitch=0;if(r[2]!==undefined)player.yaw=0;curZone=null;hudKey='';profeClose();toast('<span class="label">Modo profesor</span><br>'+d.n);}
function profeCSS(){if($('profe'))return;const st=document.createElement('style');st.textContent=`#profe{position:fixed;inset:0;z-index:60;background:rgba(10,8,6,.72);display:flex;align-items:center;justify-content:center}
#profe .pb{background:#241b14;color:#f1e8d8;border:1px solid #d9874a;max-width:760px;width:calc(100% - 32px);max-height:88vh;display:flex;flex-direction:column;padding:16px;gap:10px;font-family:Alegreya,Georgia,serif}
#profe h2{margin:0;font-family:Marcellus,Georgia,serif;font-weight:400;color:#ecc29a}#profe input{width:100%;padding:8px;font-size:16px;background:#14100c;color:#f1e8d8;border:1px solid #6a5040}
#profe .acts{display:flex;flex-wrap:wrap;gap:6px}#profe button{background:#3a2c20;color:#f1e8d8;border:1px solid #6a5040;padding:5px 9px;cursor:pointer;font:inherit;font-size:14px}#profe button:hover{border-color:#d9874a}
#profe .list{overflow:auto;flex:1;min-height:120px;border-top:1px solid #4a3a2c}#profe .it{display:flex;gap:8px;padding:5px 4px;cursor:pointer;border-bottom:1px solid #2f241a}#profe .it:hover,#profe .it.sel{background:#3a2c20}#profe .it i{color:#ecc29a;min-width:68px;font-size:13px}
#profe .sub{font-size:13px;color:#bba98f}`;document.head.appendChild(st);}
function profeOpen(){if(ui!=='play'&&ui!=='journal')return;if(ui==='journal')closeModals();profeCSS();releasePointer();ui='profe';
  const d=document.createElement('div');d.id='profe';d.innerHTML='<div class="pb"></div>';document.body.appendChild(d);d.addEventListener('mousedown',e=>{if(e.target===d)profeClose();});
  const b=d.querySelector('.pb');if(!PROFE.ok){b.innerHTML='<h2>Modo profesor</h2><p>Este panel permite ir al instante a cualquier lugar para enseñar el juego en clase. Escribe la clave del profesorado.</p><input id="profeK" type="password" placeholder="Clave" autocomplete="off"><div class="acts"><button id="profeX">Cerrar</button></div><p class="sub">La clave está en la Guía del diario, en «Para el profesorado».</p>';
    const k=$('profeK');k.focus();k.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape')profeClose();if(e.key==='Enter'){if(norm(k.value.replace(/[`º]/g,'').trim())===PROFE.key){PROFE.ok=true;try{localStorage.setItem('nostos-profe','1');}catch(e){}profeClose();profeOpen();}else{k.value='';k.placeholder='Clave incorrecta';}}});$('profeX').onclick=profeClose;return;}
  const ro=MODE==='roma',mon=ro?'sestercios':'óbolos';
  b.innerHTML='<h2>Modo profesor</h2><input id="profeQ" placeholder="Buscar un lugar, una persona o una región… (Intro para ir)" autocomplete="off"><div class="acts" id="profeA"></div><div class="list" id="profeL"></div><p class="sub">Los atajos cambian la partida guardada en este navegador. Para una demostración limpia, usa luego «Empezar de nuevo». Esc cierra.</p>';
  const A=$('profeA'),act=(t,fn)=>{const x=document.createElement('button');x.textContent=t;x.onclick=()=>{fn();save();updateStats();toast('<span class="label">Modo profesor</span><br>'+t);};A.appendChild(x);};
  act('Amanecer',()=>{clock.h=7;updateSky();});act('Mediodía',()=>{clock.h=13;updateSky();});act('Noche',()=>{clock.h=22;updateSky();});
  act('Estación siguiente',()=>{const c0=calNow().season.id;let k=0;while(calNow().season.id===c0&&k++<40)state.day++;evCrowd(true);});
  act('Próxima fiesta',()=>{const d=state.day||1;for(let k=d+1;k<d+120;k++)if(festOfDay(k)){state.day=k;break;}const ev=todayEvent();if(ev)clock.h=ev.h0+0.5;updateSky();evCrowd(true);});
  act('+500 '+mon,()=>{state.obols+=500;});
  act('Caballo',()=>{hz().own=true;});act('Alas de Dédalo',()=>{wz().own=true;});
  act('Cambiar de personaje',()=>{profeClose();setTimeout(()=>pjDlg(),50);});act('Llave del Olimpo',()=>{state.olyKey=1;});act('Casa propia',()=>{cz().st=3;});act('Barco propio',()=>{const b=bz();b.st=3;b.name=b.name||barcoDef().def;barcoVis();});
  {const x=document.createElement('button');x.textContent='Cuadernos de viaje de los alumnos';x.style.borderColor='#d9874a';x.onclick=fxProfeCuadernos;A.appendChild(x);}
  const Lst=profeDests(),q=$('profeQ'),L=$('profeL');let shown=[],sel=0;
  const draw=()=>{const w=norm(q.value).split(/\s+/).filter(Boolean);shown=Lst.filter(d=>{const n=norm(d.t+' '+d.n);return w.every(x=>n.includes(x));}).slice(0,200);sel=Math.min(sel,shown.length-1);
    L.innerHTML='';shown.forEach((d,i)=>{const e=document.createElement('div');e.className='it'+(i===sel?' sel':'');e.innerHTML='<i>'+d.t+'</i><span></span>';e.lastChild.textContent=d.n;e.onclick=()=>profeGo(d);L.appendChild(e);});};
  q.addEventListener('input',()=>{sel=0;draw();});q.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape')profeClose();else if(e.key==='Enter'&&shown[sel])profeGo(shown[sel]);else if(e.key==='ArrowDown'){sel=Math.min(shown.length-1,sel+1);draw();e.preventDefault();}else if(e.key==='ArrowUp'){sel=Math.max(0,sel-1);draw();e.preventDefault();}});
  draw();q.focus();}
