function pjDlg(done){dlg={n:null};ui='dialog';releasePointer();const ro=MODE==='roma';$('dGlyph').textContent='✎';setName('Tu personaje');$('dTitle').textContent=ro?'Llegas a Roma desde muy lejos':'Llegas a Atenas desde muy lejos';
  const p=pjz()||{name:'',g:''};let g=p.g||'';
  $('dBody').innerHTML='<p>Antes de entrar en la ciudad, ¿quién eres?</p><p><label>Tu nombre <input id="pjName" maxlength="20" autocomplete="off" style="font:inherit;padding:4px 8px;width:14em"></label></p><p><label>Tu patria '+fxOrigSelect()+'</label></p><p class="sub">Quienes te conozcan te llamarán por tu nombre. '+(ro?'En Roma, las mujeres no votan ni ocupan cargos, pero se mueven por la ciudad, tienen negocios y heredan.':'En la Atenas del siglo IV, las mujeres no votan ni van a la Asamblea, y las de buena familia salen poco de casa. Muchas otras, en cambio, trabajan en el mercado, en las fuentes o en los santuarios.')+' El juego te deja ir a todas partes, y a veces la gente se sorprenderá.</p>';
  const o=$('dOpts');o.innerHTML='';const inp=$('pjName');inp.value=p.name||'';
  const fin=()=>{const nm=(inp.value||'').replace(/[<>&"]/g,'').trim().slice(0,20);if(!nm){inp.placeholder='Escribe un nombre';inp.focus();return;}if(!g)return;const os=$('pjOrig');state.pj={name:nm,g,o:os?os.value:(p.o||'')};save();pjAvatar();fxRelabel();closeDialog();requestPointer&&requestPointer();
    toast('<span class="label">'+(g==='f'?'Bienvenida':'Bienvenido')+', '+nm+'</span><br>'+(ro?'Que los dioses te acompañen por Roma.':'Que los dioses te acompañen por Atenas.'));if(done)done();};
  const mk=(t,v)=>{const b=document.createElement('button');b.innerHTML='<span class="n">'+(o.children.length+1)+'</span><span>'+t+'</span>';b.onclick=()=>{g=v;[...o.children].forEach(x=>x.classList.remove('quiz'));b.classList.add('quiz');};if(g===v)b.classList.add('quiz');o.appendChild(b);};
  mk('Soy un hombre','m');mk('Soy una mujer','f');
  const go=document.createElement('button');go.innerHTML='<span class="n">3</span><span>Entrar en la ciudad</span>';go.onclick=fin;o.appendChild(go);
  inp.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter')fin();});$('dialog').hidden=false;setTimeout(()=>inp.focus(),50);}
