CONVS_ATENAS.push(
 {tema:'La batalla',at:'place:salamina_batalla',cast:[['Neocles',CV.v],['Lisis',CV.s]],lines:[[1,'Abuelo, ¿desde dónde miraba Jerjes?'],[0,'Desde allí enfrente, desde el monte Egaleo, sentado en un trono de oro, con escribas que apuntaban quién luchaba bien.'],[1,'¿Y lo apuntaron?'],[0,'Apuntaron muchas cosas. Pero al final del día no quedaba nada bueno que apuntar. Dicen que la reina Artemisia de Halicarnaso hundió una nave de su propio bando para escapar, y Jerjes, desde lejos, creyó que había hundido una griega.'],[1,'¿Y qué dijo?'],[0,'«Mis hombres se han vuelto mujeres, y mis mujeres, hombres». Eso cuenta Heródoto.']]},
 {tema:'El regreso',at:'place:melos_regreso',cast:[['Timo',CV.m3],['Arista',CV.f2]],lines:[[0,'Han vuelto a llegar dos de Eubea. Dicen que eran niños de aquí, vendidos en el 416.'],[1,'¿Se acuerdan de algo?'],[0,'Uno se acordaba de una higuera junto a la puerta de su casa. Lo llevamos a la calle de arriba, y allí estaba la higuera.'],[1,'¿Y la casa?'],[0,'Vive en ella un colono ateniense que no se ha querido ir. Se ha casado con una de las nuestras.'],[1,'Así es esto ahora. Todos mezclados.']]},
 {tema:'Pitágoras',at:'place:samos_hereo',cast:[['Méton',CV.m],['Hípaso',CV.j]],lines:[[1,'Mi maestro dice que todo son números. Que la música es número, y el cielo también.'],[0,'Eso lo decía Pitágoras, que era de aquí. Se fue a Crotona, en Italia, harto de Polícrates.'],[1,'Y que el alma pasa de un cuerpo a otro. Dicen que una vez oyó llorar a un perro al que pegaban y gritó: «¡Para, es el alma de un amigo, lo reconozco por la voz!».'],[0,'Eso lo cuenta Jenófanes, que se reía de él. Yo, por si acaso, no pego a los perros.']]},
 {tema:'El vino',at:'place:quios_vino',cast:[['Teocles',CV.m2],['Apolófanes',CV.m]],lines:[[0,'Este año la uva ha venido dulce. Las ánforas de la cosecha ya están vendidas a un mercader de Atenas.'],[1,'¿Antes de llenarlas?'],[0,'Antes. En Atenas pagan lo que sea por poner vino de Quíos en la mesa.'],[1,'Y luego lo beberán mezclado con agua, como todo el mundo: tres partes de agua por una de vino.'],[0,'Que lo mezclen con lo que quieran. El dinero no se mezcla.']]},
 {tema:'La isla nueva',at:'place:rodas_ciudad',cast:[['Damágoras',CV.m],['Filina',CV.f]],lines:[[0,'Mi familia es de Lindos desde siempre. Me costó venir a vivir aquí.'],[1,'A mí no. En Camiro solo había cabras y viejos. Aquí llegan barcos de todas partes.'],[0,'Pero el templo de Atenea Lindia sigue allí, en lo alto de la roca. Allí está escrito el poema de Píndaro para Diágoras, en letras de oro.'],[1,'Pues ve a verlo en las fiestas, y vuelve. Aquí está el trabajo.']]},
 {tema:'La guerra civil',at:'place:corcira_stasis',cast:[['Arcesilao',CV.v],['Nicón',CV.m3]],lines:[[1,'¿Es verdad que en el 427 la gente se mataba en los templos?'],[0,'Yo lo vi. A unos suplicantes los encerraron en el santuario de Hera, y se ahorcaron de los árboles antes que caer en manos de los otros.'],[1,'¿Por qué tanto odio, si eran vecinos?'],[0,'Precisamente por eso. A un enemigo de fuera lo olvidas. Al vecino que te quitó la casa lo ves cada mañana en el mercado.'],[1,'¿Y ahora?'],[0,'Ahora nos saludamos. Y no olvidamos.']]},
 {tema:'El trigo',at:'place:bizancio_bosforo',cast:[['Calícrates',CV.m2],['Hermón',CV.m3]],lines:[[0,'Tres barcos de trigo esperando el viento del norte. Si no sopla, se quedan aquí otra semana.'],[1,'Mejor. Así comen en nuestras tabernas y pagan en nuestros almacenes.'],[0,'Los atenienses no piensan igual. Cada día que el trigo no llega, en el Pireo sube el precio.'],[1,'Que lo cultiven ellos. Ah, no, que su tierra solo da olivos y piedras.']]},
 {tema:'La liga',at:'place:olinto_liga',cast:[['Licofrón',CV.m],['Mnasipo',CV.m2]],lines:[[0,'Hoy en la Asamblea votamos enviar embajadores a Acanto otra vez.'],[1,'¿Para qué? Ya dijeron que no quieren ser de la liga.'],[0,'Si no entran por las buenas, entrarán por las malas. No puede haber una ciudad libre en medio de nuestra tierra.'],[1,'Ten cuidado: eso mismo decían los atenienses de las islas. Y mira cómo acabaron.']]},
 {tema:'Los hilotas',at:'place:pilos_esfacteria',cast:[['Aristón',CV.s],['Damón',CV.m3]],lines:[[0,'Mi abuelo nadaba de noche hasta la isla con odres de harina atados a una cuerda.'],[1,'Los espartanos le prometieron la libertad, ¿no?'],[0,'A él y a otros. Poco después, todavía en guerra, los espartanos anunciaron que liberarían a los hilotas más valientes. Se presentaron dos mil. Les pusieron coronas y los llevaron a los templos.'],[1,'¿Y qué pasó?'],[0,'Que nadie volvió a verlos. Lo cuenta Tucídides. Querían saber quiénes eran los más peligrosos.']]},
 {tema:'Después de la guerra',at:'place:decelia_fuerte',cast:[['Estratón',CV.v],['Cárito',CV.f2]],lines:[[0,'Cuando volvimos, en la casa no quedaba ni la puerta. Se la habían llevado para hacer fuego.'],[1,'Nosotros encontramos dentro a un espartano enterrado. Lo dejamos donde estaba: los muertos no tienen bando.'],[0,'Dicen que ahora hay paz para siempre, la paz del Rey.'],[1,'También dijeron eso en la paz de Nicias. Duró seis años.']]});
CURIOS.push(
 {id:'c_artemisia',at:'salamina_batalla',h:'Una reina en la flota persa',t:'En Salamina, una de las naves de Jerjes la mandaba una mujer: Artemisia, reina de Halicarnaso. Según Heródoto, fue la única que aconsejó al rey no combatir en el estrecho. Los atenienses ofrecieron una recompensa de diez mil dracmas a quien la capturara viva: les ofendía que una mujer luchara contra ellos.',s:'Heródoto VIII 68-93'},
 {id:'c_melos_lascas',at:'obsidiana',h:'Cuchillas más finas que el acero',t:'El filo de una lasca de obsidiana puede ser mucho más fino que el de un bisturí de acero. Aún hoy algunos cirujanos usan bisturís de obsidiana para cortes muy finos.',s:'Arqueología de Melos (Phylakopi)'},
 {id:'c_eupalino',at:'tunel_eupalino',h:'Casi a ciegas',t:'Cuando las dos cuadrillas del túnel de Eupalino se encontraron, tras más de quinientos metros cada una, el desvío lateral era de unos pocos metros y la diferencia de altura, de menos de un metro. El agua no corría por el túnel mismo, sino por una zanja más profunda excavada en su suelo, con la pendiente justa.',s:'H. J. Kienast, Die Wasserleitung des Eupalinos (1995)'},
 {id:'c_quios_esfinge',at:'quios_vino',h:'Una esfinge en la moneda',t:'Las monedas de Quíos llevaban una esfinge sentada y, a menudo, un ánfora de vino. La esfinge ya aparece en sus monedas desde el siglo VI. Era como una marca de calidad: todo el mundo la reconocía.',s:'Numismática de Quíos'},
 {id:'c_rodas_coloso',at:'rodas_coloso',h:'No tenía las piernas abiertas',t:'La imagen del Coloso de Rodas con un pie en cada orilla del puerto, dejando pasar los barcos por debajo, es un invento de la Edad Media. Con el bronce de la época, una estatua así se habría caído. Seguramente estaba de pie, en tierra, con las piernas juntas.',s:'Plinio, Historia natural XXXIV 41; Estrabón XIV 2.5'},
 {id:'c_gorgona',at:'corcira_corinto',h:'La Gorgona que protege',t:'La Gorgona del frontón del templo de Ártemis de Corcira mide casi tres metros. No es una decoración para asustar a los fieles, sino para proteger el templo: su mirada petrificaba a los enemigos. A sus lados aparecen sus hijos, Pegaso y Crisaor, nacidos de su sangre cuando Perseo le cortó la cabeza.',s:'Museo Arqueológico de Corfú'},
 {id:'c_bizancio_bou',at:'bizancio_ciegos',h:'El paso de la vaca',t:'Bósforo significa «paso de la vaca». Según el mito, la joven Ío, convertida en vaca por Zeus para esconderla de Hera, cruzó a nado este estrecho huyendo del tábano que la diosa le había enviado.',s:'Esquilo, Prometeo encadenado 732-734'},
 {id:'c_olinto_balas',at:'olinto_futuro',h:'Balas con mensaje',t:'En Olinto se han encontrado cientos de proyectiles de plomo de honda del asedio del 348. Algunos llevan escrito el nombre de Filipo, y otros, mensajes burlones para el enemigo, como «¡toma esto!».',s:'D. M. Robinson, Excavations at Olynthus X (1941)'},
 {id:'c_pilos_laconismo',at:'pilos_escudo',h:'Una respuesta muy espartana',t:'Un ateniense le preguntó con burla a uno de los prisioneros de Esfacteria si los espartanos valientes eran los que habían muerto. Él contestó que una flecha («huso», la llamó) valdría mucho si supiera distinguir a los valientes.',s:'Tucídides IV 40'},
 {id:'c_decelia_queso',at:'decelia_fratria',h:'El mercado de los de Decelia',t:'En Atenas, los de Decelia se reunían en un punto concreto del Ágora, junto a la barbería que había al lado de los Hermes. Allí se los podía encontrar para preguntar por alguien del demo: así se sabe por un discurso de Lisias.',s:'Lisias XXIII 3'});
// ---- fauna de las calles y las casas (modelos de modelos/animales.blend): perros, gatos, comadrejas, gallinas, gansos, cerdos, cabras,
// burros cargados, lechuzas, codornices, pavos reales, un mono, la culebra de la casa y un loro. Cada uno se anima solo cerca del jugador
Object.assign(ROLE_C,{belly:'#e8dcc0',nose:'#1a1410',eye:'#120c08',horn:'#b8a888',snout:'#d89a8a',feather:'#c8a070',wing:'#a07a4a',tail:'#2a3a2a',comb:'#c4282a',beak:'#d8a040',face:'#e8d8c0',eyey:'#e8b828',peacock:'#2a5aa8',train:'#3a6a3a',eyespot:'#1a3a8a',snake:'#5a5a3a',parrot:'#3a9a3a'});
const FAUNA=[],FCOL={dog:['#6b4a2e','#a07a4a','#2a2018','#c9a46a','#8a6a4a'],cat:['#8a7a6a','#c9a46a','#2a2420','#e8dcc8','#6a5040'],hen:['#a0603a','#c9a46a','#e8dcc8','#5a3a2a'],goat:['#3a3028','#6b4a2e','#2a2018','#a08a6a','#e8dcc8'],pig:['#d8a08a','#5a4a40','#c89080']};
function animal(sp,o){o=o||{};const g=new THREE.Group(),ro={};const c=o.c||{};
  for(const k of['coat','feather','wing','tail','belly','face','comb','beak','peacock','train','eyespot','snake','parrot','horn','snout','nose','eye','eyey','hoof'])ro[k]=lam(c[k]||ROLE_C[k]);
  const P=n=>{const p=glbPart('A_'+sp+'_'+n,ro);if(p)g.add(p);return p;};
  const body=P('body'),head=P('head'),tail=P('tail'),legs=['leg_fl','leg_fr','leg_bl','leg_br','leg_l','leg_r'].map(P).filter(Boolean);const ex={};for(const n of o.extra||[])ex[n]=P(n);
  g.scale.setScalar(o.s||1);scene.add(g);return{g,body,head,tail,legs,ex,sp};}
const FAUNA_INFO={
 moloso:{A:['Perro moloso','Del Epiro, en el noroeste de Grecia: el gran perro guardián, macizo, de cabeza ancha y hocico corto, con papada. Defiende casas y rebaños de los lobos y de los ladrones. Aristóteles escribe que los molosos de pastor son excelentes por su tamaño y su valor. Se dice que el rey Alejandro de Epiro presumía de ellos.','Aristóteles, Historia de los animales IX 1, 608a; Aristófanes, Tesmoforiantes 416'],R:['Perro moloso','El gran perro guardián de casas, granjas y rebaños, venido del Epiro: de él descienden los perros de presa del anfiteatro. Varrón aconseja que el perro de pastor sea blanco, para no confundirlo de noche con un lobo, y Columela, que el guardián de la casa sea negro, para que asuste más al ladrón.','Varrón, Sobre la agricultura II 9; Columela VII 12; Grattio, Cinegético 181']},
 laconio:{A:['Perro laconio','El perro de caza de Esparta: fino, de pecho hondo, patas largas y hocico estrecho, rápido y de buen olfato. Jenofonte, que cazaba con ellos, distingue dos tipos: los «castorios», que descienden del perro de Cástor, y los «zorrunos», que se creía que eran cruce con zorro. Les ponía nombres cortos para llamarlos bien: Psique, Hebe, Bía…','Jenofonte, Cinegético 3-7; Píndaro, fr. 106'],R:['Perro laconio','Los perros de caza de Laconia siguen siendo los más apreciados en Roma: rápidos, finos y de buen olfato. Grattio y Virgilio los recomiendan para la caza mayor.','Grattio, Cinegético 212; Virgilio, Geórgicas III 405']},
 cretense:{A:['Perro cretense','De Creta, la isla de Minos: un perro de caza mediano, ágil y resistente, con las orejas erguidas y la cola enroscada. Los cretenses lo cruzan con el laconio para tener perros rápidos y de buen olfato a la vez.','Aristóteles, Historia de los animales IX 1; Jenofonte, Cinegético 10.1'],R:['Perro cretense','Un perro de caza ágil, de las montañas de Creta, que los romanos aprecian para correr por terreno difícil.','Grattio, Cinegético 212; Opiano, Cinegética I 373']},
 melitense:{A:['Perrito de Melita','El perrito faldero de pelo largo y blanco, quizá de la isla de Melita, la actual Malta. Lo miman las damas y los niños, y aparece en las estelas de las tumbas jugando con sus dueños. Teofrasto se burlará del presumido que, cuando se le muere uno, le hace una tumba con una inscripción.','Aristóteles, Historia de los animales IX 6, 612b; Teofrasto, Caracteres 21; Estrabón VI 2.11'],R:['Perrito de Melita','El faldero de las damas romanas: pequeño, blanco, de pelo largo. Marcial dedica un epigrama a Issa, la perrita de su amigo Publio, «más pura que un beso de paloma», que avisaba con la patita cuando quería bajar de la cama.','Marcial I 109; Estrabón VI 2.11']},
 umbro:{R:['Perro umbro','Un sabueso de Umbría, de orejas grandes y caídas, que sigue el rastro con el hocico pegado al suelo mejor que ningún otro. Grattio dice que tiene buen olfato pero poco valor: encuentra la presa y luego no se atreve con ella.','Grattio, Cinegético 171-173']},
 britano:{R:['Perro británico','Desde que Roma conquistó Britania llegan de allí perros fuertes y bravos, muy apreciados para la caza y, dicen, para la guerra. Estrabón cuenta que los perros de caza están entre lo que exporta la isla, junto con el trigo, el ganado, el oro y los esclavos.','Estrabón IV 5.2; Grattio, Cinegético 174-178']},
 dog:{A:['Perro callejero','Un perro sin raza, de los muchos que viven en las calles comiendo sobras. Los perros están por todas partes: guardan casas y rebaños, acompañan a los cazadores y deambulan por las calles comiendo sobras. Los molosos del Epiro son enormes y feroces; los laconios, finos y rápidos, son los mejores para la caza, según Jenofonte; y los pequeños perros de Melita, de pelo largo, son el capricho de las damas y aparecen en las estelas de las tumbas. Diógenes y los suyos vivían «como perros»: de ahí el nombre de «cínicos».','Jenofonte, Cinegético 3-4; Aristóteles, Historia de los animales IX 1; Diógenes Laercio VI'],
     R:['Perro callejero','Ningún portero romano trabaja sin perro. En el suelo de muchas entradas, un mosaico avisa: CAVE CANEM, «cuidado con el perro». Varrón recomienda perros guardianes grandes, de voz potente y de color claro, para no confundirlos con un lobo de noche. Por las calles corren perros sin dueño, mestizos de todas las clases, que viven de las sobras de los mercados y de las cocinas.','Varrón, Sobre la agricultura II 9; Columela VII 12; Grattio, Cinegético 154-202; Estrabón IV 5.2; Petronio, Satiricón 29; Marcial I 109']},
 cat:{R:['Gato','Los gatos llegaron de Egipto, donde eran sagrados. En Roma ya no son tan raros: cazan ratones en los almacenes y en las casas, y en Pompeya hay un mosaico de un gato atrapando un pájaro. Los griegos de hace cuatro siglos casi no los conocían: para los ratones usaban comadrejas.','Heródoto II 66-67; mosaico del gato de la Casa del Fauno, Pompeya']},
 weasel:{A:['Comadreja','Los griegos casi no tienen gatos: para cazar ratones crían comadrejas, o hurones, en las casas y en los graneros. Cruzarse con una comadreja por la calle trae mala suerte: hay que esperar a que pase alguien o tirar tres piedras al otro lado del camino.','Aristóteles, Historia de los animales IX 6; Aristófanes, Asambleístas 792; Teofrasto, Caracteres 16 (el supersticioso)']},
 hen:{A:['Gallina','Las gallinas y los gallos llegaron a Grecia desde Persia: por eso los llaman «el ave persa». Hoy hay gallinas en casi todos los patios. Los huevos se comen cocidos, y los gallos se crían para las peleas y para los sacrificios: Sócrates, antes de morir, pidió que se sacrificara un gallo a Asclepio.','Aristófanes, Aves 483-485; Platón, Fedón 118a'],R:['Gallina','En Roma se crían gallinas por todas partes; los ricos las ceban y comen huevos «del huevo a las manzanas», del primer plato al postre. Las gallinas sagradas de los augures predicen el futuro: si comen con ganas, los dioses están de acuerdo.','Columela VIII 2-7; Cicerón, Sobre la adivinación II 72']},
 rooster:{A:['Gallo','El gallo es el ave de la pelea. Cuentan que Temístocles, de camino a luchar contra los persas, vio pelear a dos gallos y animó a sus soldados: «¡Ellos luchan sin patria ni dioses que defender!». Desde entonces, cada año hay una pelea de gallos en el teatro, pagada por la ciudad.','Eliano, Historias curiosas II 28'],R:['Gallo','Los romanos también organizan peleas de gallos y de codornices. El gallo canta para despertar a los vivos y espantar a los fantasmas, que solo andan de noche.','Columela VIII 2; Plinio, Historia natural X 46-50']},
 goose:{R:['Ganso','Los gansos del Capitolio son sagrados para Juno. Cuando los galos subieron de noche a la roca, en el 390 a.C., los perros no ladraron, pero los gansos graznaron y despertaron a Manlio, que rechazó el asalto. Desde entonces se crían a costa del Estado.','Livio V 47; Plinio, Historia natural X 51'],A:['Ganso','Los gansos se crían en los patios: dan carne, huevos y plumas, y son tan buenos guardianes como un perro. Penélope, en la Odisea, cuidaba veinte gansos y soñó que un águila los mataba: era Ulises, que volvía.','Homero, Odisea XIX 536-553']},
 pig:{A:['Cerdo','El cerdo es el animal de sacrificio más barato. En las Tesmoforias se sacrifican lechones a Deméter, y los iniciados de Eleusis lavan un cerdito en el mar antes de los Misterios. Un lechón cuesta unas tres dracmas.','Aristófanes, Paz 374; Acarnienses 764-817'],R:['Cerdo','El cerdo es la carne de los romanos. Hay un mercado de cerdos en Roma, el Foro Suario, y Plinio dice que el cerdo tiene cincuenta sabores distintos. En los sacrificios, la suovetaurilia, se ofrecen juntos un cerdo, una oveja y un toro.','Plinio, Historia natural VIII 209; Catón, Sobre la agricultura 141']},
 goat:{A:['Cabra','Las cabras son los animales de los montes pobres del Ática: dan leche y queso, y la piel sirve para odres y para el escudo de Atenea, la égida. Son una plaga para los árboles jóvenes, así que no se las deja entrar en los olivares.','Aristóteles, Historia de los animales VIII; Varrón II 3'],R:['Cabra','Las cabras dan leche y queso, y se ofrecen a Fauno en las Lupercales. Varrón aconseja no dejarlas entrar en los olivares recién plantados, porque los muerden y los secan.','Varrón, Sobre la agricultura II 3; Ovidio, Fastos II']},
 donkey:{A:['Burro','Los burros y los mulos lo transportan todo: leña del Parnes, cántaros de vino, sacos de grano, piedra. En Atenas, los arrieros los cargan con unos cestos a cada lado. Un buen mulo cuesta más que un esclavo.','Aristófanes, Ranas 1-30 (el burro de Jantias); Jenofonte, Económico'],R:['Mulo','Los mulos tiran de los carros que de noche llenan las calles de Roma: de día está prohibido circular con carros, salvo los de las obras públicas. Juvenal se queja de que en Roma no se puede dormir.','Ley Julia municipal (45 a.C.); Juvenal, Sátiras III 232-238']},
 owl:{A:['Lechuza','La lechuza es el ave de Atenea: está en las monedas de plata de la ciudad, que todos llaman «lechuzas». Anida en la Acrópolis y caza ratones de noche. «Llevar lechuzas a Atenas» es hacer algo inútil, como llevar agua al mar.','Aristófanes, Aves 301 y 1106']},
 quail:{A:['Codorniz','En Atenas se apuesta en las peleas de codornices. Dicen que, en su primera Asamblea, a Alcibíades se le escapó una codorniz que llevaba bajo el manto: todos se pusieron a perseguirla, y el piloto Antíoco la atrapó y se la devolvió. Se hicieron amigos para siempre.','Plutarco, Alcibíades 10; Platón, Eutidemo 290d']},
 peacock:{A:['Pavo real','Los pavos reales son una rareza traída de Persia. Hace unos años, Demo, el hijo de Pirilampes, los criaba en su casa y los enseñaba a quien quisiera verlos en la luna nueva: venían a verlos hasta de Esparta y de Tesalia. Un pavo real vale una fortuna.','Ateneo IX 397c-d (citando a Antifonte); Aristófanes, Aves 102'],R:['Pavo real','El pavo real es el ave de Juno: dicen que la diosa puso en su cola los cien ojos de Argos. El orador Hortensio fue el primero en servirlo en un banquete; desde entonces los ricos los crían en sus jardines, y los comen.','Ovidio, Metamorfosis I 722-723; Plinio, Historia natural X 45']},
 monkey:{A:['Mono','Un mono de compañía, con una cadena: un capricho de ricos. Teofrasto se burlará del presumido que, para que lo miren, se pasea con un mono, un perrito de Melita y una paloma de Sicilia.','Teofrasto, Caracteres 21']},
 snake:{A:['Culebra de la casa','Muchas casas tienen su culebra, inofensiva, que se considera protectora del hogar y de la despensa, y se asocia a Zeus Ktesios, el que guarda los bienes. Nadie la mata: se le deja un cuenco de leche y miel.','Iseo VIII 16 (Zeus Ktesios); Heródoto VIII 41 (la serpiente de la Acrópolis)'],R:['Serpiente del larario','Las serpientes pintadas en los lararios son el genio del lugar, su espíritu protector. En algunas casas hay serpientes de verdad, mansas, que los niños llevan al cuello y que limpian la casa de ratones.','Plinio, Historia natural XXIX 72; pinturas de lararios de Pompeya']},
 parrot:{R:['Loro','Los loros vienen de la India y aprenden a hablar: los ricos les enseñan a decir «¡Ave, César!». Ovidio escribió un poema fúnebre para el loro de su amada, Corina, que imitaba la voz humana mejor que ningún otro pájaro.','Ovidio, Amores II 6; Plinio, Historia natural X 117']}};
function faunaInfo(sp){const I=FAUNA_INFO[sp];return I&&(I[MODE==='roma'?'R':'A']||I.A||I.R);}
// comportamientos: 'wander' (va de un punto a otro de su zona), 'peck' (gallinas), 'still' (quieta, gira la cabeza), 'lie' (perro tumbado), 'sit', 'follow'
function faunaAdd(sp,x,z,o){o=o||{};const A=animal(o.model||sp,o);if(!A.body){scene.remove(A.g);return null;}const y=o.y!==undefined?o.y:floorAt(x,z);A.g.position.set(x,y,z);A.g.rotation.y=o.a!==undefined?o.a:R()*TAU;
  const F=Object.assign({A,sp,info:o.info||sp,x,z,cx:x,cz:z,r:o.r||8,beh:o.beh||'wander',spd:o.spd||(sp==='dog'?1.4:sp==='hen'||sp==='rooster'?0.6:0.9),tx:x,tz:z,w:R()*4,ph:R()*10,y0:o.y,fixedY:o.y!==undefined},o.F||{});
  if(F.beh==='lie')faunaPose(F,'lie');if(F.beh==='sit')faunaPose(F,'sit');FAUNA.push(F);
  F.obj={kind:'fauna',x,z,F,data:{name:(faunaInfo(F.info)||[sp])[0],role:''}};return F;}
function faunaPose(F,p){const L=F.A.legs;if(p==='lie'){F.A.g.position.y-=0.42*(F.A.g.scale.x);L.forEach((l,i)=>{l.rotation.x=i<2?-1.45:1.3;});if(F.A.body)F.A.body.position.y=0;}
  else if(p==='sit'){if(F.A.body)F.A.body.rotation.x=-0.45;L.forEach((l,i)=>{l.rotation.x=i<2?0.25:-1.2;});}}
function faunaTick(dt){const T=performance.now()/1000,px=player.x,pz=player.z;FAUNA.cullT=(FAUNA.cullT||0)+dt;const cull=FAUNA.cullT>0.4;if(cull)FAUNA.cullT=0;
  FAUNA.fr=((FAUNA.fr||0)+1)%3;
  for(const F of FAUNA){const g=F.A.g;if(cull){g.visible=Math.abs(g.position.x-px)<190&&Math.abs(g.position.z-pz)<190;if(F.drv)F.drv.visible=g.visible;}if(!g.visible)continue;if(FAUNA.fr&&Math.abs(g.position.x-px)+Math.abs(g.position.z-pz)>90)continue;   /* lejos: uno de cada tres fotogramas */
    const A=F.A;if(F.stray&&dogCurious(F,dt,T))continue;
    if(F.beh==='follow'&&F.lead){const L=F.lead.g?F.lead.g.position:F.lead;const ox=L.x+(F.ox||1),oz=L.z+(F.oz||1);F.tx=ox;F.tz=oz;F.w=0;}
    if(F.beh==='road'){const rd=F.road;let tp=rd.pts[F.dir>0?F.seg+1:F.seg];const tx=tp[0]+1.8,tz=tp[1]+1.8,dx=tx-g.position.x,dz=tz-g.position.z,d=Math.hypot(dx,dz);
      if(d<0.6){F.seg+=F.dir;if(F.seg<0||F.seg>=rd.pts.length-1){F.dir*=-1;F.seg=clamp(F.seg,0,rd.pts.length-2);}}
      else{const v=Math.min(d,dt*F.spd);g.position.x+=dx/d*v;g.position.z+=dz/d*v;g.position.y=terrainH(g.position.x,g.position.z);g.rotation.y+=wrapA(Math.atan2(dx,dz)-g.rotation.y)*Math.min(1,dt*4);F.ph+=v*5;const s=Math.sin(F.ph);A.legs[0].rotation.x=s*0.4;A.legs[3].rotation.x=s*0.4;A.legs[1].rotation.x=-s*0.4;A.legs[2].rotation.x=-s*0.4;if(A.head)A.head.rotation.x=Math.sin(F.ph*2)*0.05;}
      if(F.drv){const a=g.rotation.y,x=g.position.x+Math.cos(a)*1.1-Math.sin(a)*0.6,z=g.position.z-Math.sin(a)*1.1-Math.cos(a)*0.6;F.drv.position.set(x,terrainH(x,z),z);F.drv.rotation.y=a;F.drv.visible=g.visible;personWalk(F.drv,F.ph,1);}
      F.obj.x=g.position.x;F.obj.z=g.position.z;continue;}
    if(F.beh==='wander'||F.beh==='peck'||F.beh==='follow'){
      F.w-=dt;const dx=F.tx-g.position.x,dz=F.tz-g.position.z,d=Math.hypot(dx,dz);
      if(d<0.25||F.w>0){if(F.beh!=='follow'&&F.w<=0){F.w=F.beh==='peck'?rr(1,5):rr(2,9);const a=R()*TAU,r=Math.sqrt(R())*F.r;F.tx=F.cx+Math.cos(a)*r;F.tz=F.cz+Math.sin(a)*r;
          // solo por suelo al mismo nivel que su sitio: que los gansos del Capitolio no trepen por el acantilado ni los animales por los muros
          if(!F.fixedY){if(F.h0===undefined)F.h0=floorAt(F.cx,F.cz);let ok=false;for(let q=0;q<5&&!ok;q++){if(q){const b=R()*TAU,rb=Math.sqrt(R())*F.r;F.tx=F.cx+Math.cos(b)*rb;F.tz=F.cz+Math.sin(b)*rb;}const hm=floorAt((F.tx+g.position.x)/2,(F.tz+g.position.z)/2);ok=Math.abs(floorAt(F.tx,F.tz)-F.h0)<1.2&&Math.abs(hm-F.h0)<1.2;}if(!ok){F.tx=F.cx;F.tz=F.cz;}}}
        A.legs.forEach(l=>l.rotation.x*=0.85);if(A.head)A.head.rotation.x=F.beh==='peck'?Math.max(0,Math.sin(T*6+F.ph))*0.9:Math.sin(T*0.7+F.ph)*0.15;if(A.head)A.head.rotation.y=Math.sin(T*0.5+F.ph)*0.5;}
      else{const v=Math.min(d,dt*F.spd*(F.beh==='follow'&&d>3?2:1));g.position.x+=dx/d*v;g.position.z+=dz/d*v;if(!F.fixedY)g.position.y=floorAt(g.position.x,g.position.z);g.rotation.y+=wrapA(Math.atan2(dx,dz)-g.rotation.y)*Math.min(1,dt*6);
        F.ph+=v*(F.A.legs.length===2?16:9)/(g.scale.x||1);const s=Math.sin(F.ph);if(A.legs.length===4){A.legs[0].rotation.x=s*0.45;A.legs[3].rotation.x=s*0.45;A.legs[1].rotation.x=-s*0.45;A.legs[2].rotation.x=-s*0.45;}else if(A.legs.length===2){A.legs[0].rotation.x=s*0.5;A.legs[1].rotation.x=-s*0.5;}
        if(A.head)A.head.rotation.x=A.legs.length===2?Math.sin(F.ph)*0.15:0;}
      F.obj.x=g.position.x;F.obj.z=g.position.z;}
    else if(A.head&&(F.beh==='still'||F.beh==='lie'||F.beh==='sit')){const near=Math.hypot(px-g.position.x,pz-g.position.z)<8;
      if(near){const a=Math.atan2(px-g.position.x,pz-g.position.z)-g.rotation.y;A.head.rotation.y+=(wrapA(a)*0.8-A.head.rotation.y)*Math.min(1,dt*3);}else A.head.rotation.y=Math.sin(T*0.4+F.ph)*0.7;}
    if(A.tail&&(F.sp==='dog'||F.sp==='cat'))A.tail.rotation.y=Math.sin(T*(F.sp==='dog'?9:1.5)+F.ph)*(F.sp==='dog'?0.5:0.3);
    if(F.sp==='peacock'&&A.ex.fan){if(F.fs===undefined){F.fs=Math.random()*40;F.fk=0;F.fsc=A.ex.fan.scale.clone();}   // la cola se abre unos 8 s cada ~25 s y despacio (antes dependía de los pasos y parpadeaba)
      const show=((T+F.fs)%25)<8;F.fk+=((show?1:0)-F.fk)*Math.min(1,dt*1.5);const k=F.fk;A.ex.fan.visible=k>0.04;const q=Math.max(0.05,k);A.ex.fan.scale.set(F.fsc.x*q,F.fsc.y*q,F.fsc.z);if(A.ex.train)A.ex.train.visible=k<0.5;}
    if(F.quail){g.position.y=F.y0+Math.max(0,Math.sin(T*5+F.ph))*0.18;g.rotation.y=F.a0+Math.sin(T*2+F.ph)*0.3;}}}
function faunaArea(n,test,tries){const out=[];for(let k=0;k<(tries||n*40)&&out.length<n;k++){const p=test();if(p&&isFree(p[0],p[1],0.6))out.push(p);}return out;}
function buildFauna(){FAUNA.length=0;if(!GLB.ok||!GLB.parts.A_dog_body)return;const ro=MODE==='roma';
  const city=()=>{if(ro){const x=rr(-700,500),z=rr(-600,500);return romaInUrbs(x,z)?[x,z]:null;}const a=R()*TAU,d=Math.sqrt(R())*700,x=WALLC.x+Math.cos(a)*d,z=WALLC.z+Math.sin(a)*d;return insideWalls(x,z,10)?[x,z]:null;};
  const pp=id=>{const p=placeAt(id);return p?[p.x,p.z]:null;};
  // perros callejeros, perros guardianes tumbados en las puertas y algún perrito faldero
  for(const p of faunaArea(18,city)){const q=R(),t=q<0.55?['dog','dog']:q<0.8?['laconian','laconio']:(ro?['umbrian','umbro']:['cretan','cretense']);faunaAdd('dog',p[0],p[1],{model:t[0],info:t[1],c:{coat:pick(FCOL.dog)},s:t[0]==='dog'?rr(0.85,1.1):1,r:25,spd:1.3,F:{stray:true}});}
  for(const p of faunaArea(8,city)){const br=ro&&R()<0.35;faunaAdd('dog',p[0],p[1],{model:'moloss',info:br?'britano':'moloso',c:{coat:br?'#6a4a30':pick(['#2a2018','#3a3028','#5a4a3a'])},beh:'lie'});}
  // cazadores con sus perros por los caminos
  {const rw=walkers.filter(w=>w.mode==='road');for(let k=0;k<Math.min(3,rw.length);k++){const w=rw[k*3%rw.length],t=ro?(k%2?['umbrian','umbro']:['laconian','laconio']):(k%2?['cretan','cretense']:['laconian','laconio']);for(let j=0;j<2;j++)faunaAdd('dog',w.g.position.x+1+j,w.g.position.z+1,{model:t[0],info:t[1],c:{coat:pick(['#a07a4a','#c9a46a','#6b4a2e','#2a2018'])},beh:'follow',F:{lead:w,ox:-0.9+j*1.8,oz:-1.2},spd:1.6});}}
  {const fem=walkers.filter(w=>w.g.userData&&w.mode==='agora').slice(0,40);for(let k=0;k<3&&k<fem.length;k++){const w=fem[k*7%fem.length];faunaAdd('dog',w.g.position.x+1,w.g.position.z+1,{model:'melitan',info:'melitense',c:{coat:'#f2ede4'},beh:'follow',F:{lead:w,ox:0.9,oz:0.6},spd:1.6});}}
  for(const H of VIDA.herds)if(Math.abs(H.cx-(ro?0:WALLC.x))<3000)faunaAdd('dog',H.cx+6,H.cz+4,{model:'moloss',info:'moloso',c:{coat:'#e8e0d0'},beh:'lie'});
  // gallinas con su gallo, en patios y callejas
  for(const p of faunaArea(14,city)){faunaAdd('rooster',p[0],p[1],{c:{feather:pick(['#a0402a','#c9862a','#3a2a20']),tail:'#1a2a20',wing:'#6a3a20'},beh:'peck',r:5});for(let k=0;k<rr(3,6);k++)faunaAdd('hen',p[0]+rr(-3,3),p[1]+rr(-3,3),{c:{feather:pick(FCOL.hen),wing:'#8a6a4a',tail:'#5a3a2a'},beh:'peck',r:5,F:{cx:p[0],cz:p[1]}});}
  // gatos (Roma) o comadrejas (Atenas)
  if(ro){for(const p of faunaArea(14,city))faunaAdd('cat',p[0],p[1],{c:{coat:pick(FCOL.cat)},beh:R()<0.5?'sit':'wander',r:10,spd:1});}
  else{for(const p of faunaArea(8,city))faunaAdd('weasel',p[0],p[1],{c:{coat:'#8a5a30',belly:'#efe2c8'},r:6,spd:2.2});}
  // cerdos y cabras
  for(const p of faunaArea(6,city))for(let k=0;k<3;k++)faunaAdd('pig',p[0]+rr(-3,3),p[1]+rr(-3,3),{c:{coat:pick(FCOL.pig)},s:k?0.55:1,r:6,F:{cx:p[0],cz:p[1]}});
  for(const H of VIDA.herds)for(let k=0;k<4;k++)faunaAdd('goat',H.cx+rr(-8,8),H.cz+rr(-8,8),{c:{coat:pick(FCOL.goat)},r:12,F:{cx:H.cx,cz:H.cz}});
  // burros cargados con su arriero, por los caminos
  for(let k=0;k<10;k++){const rd=ROADS[k%ROADS.length];if(!rd||!rd.pts||rd.pts.length<3)continue;const s=Math.floor(R()*(rd.pts.length-1)),p=rd.pts[s],ox=1.8;
    const F=faunaAdd('donkey',p[0]+ox,p[1]+ox,{c:{coat:pick(['#7a6a5a','#5a4a3a','#8a7a6a','#3a3028']),mane:'#2a2018'},extra:['mane'],beh:'road',spd:1.05,F:{road:rd,seg:s,dir:R()<0.5?1:-1}});if(!F)continue;
    const g=F.A.g,load=pick(['wood','jars','sacks']);for(const sd of[-1,1]){const b=box(0.32,0.42,0.6,lam('#8a6a3a'),sd*0.36,1.05,0,g);if(load==='wood')for(let i=0;i<3;i++){const l=new THREE.Mesh(new THREE.CylinderGeometry(0.05,0.05,1.1,6),lam('#6b4a30'));l.rotation.x=Math.PI/2;l.position.set(sd*0.36+(i-1)*0.08,1.32,0);g.add(l);}
      else if(load==='jars'){const a=new THREE.Mesh(new THREE.CylinderGeometry(0.1,0.06,0.5,8),lam('#b0603a'));a.position.set(sd*0.36,1.4,0);g.add(a);}else box(0.3,0.25,0.5,lam('#d8cdb0'),sd*0.36,1.38,0,g);}
    F.drv=makePerson({short:true,noHimation:true,chiton:pick(['#a08a62','#8a7a5a','#b9a77f']),hair:'#3a2a1e',beard:R()<0.6,staff:true});scene.add(F.drv);}
  // escenas
  if(!ro){
   // lechuzas en la Acrópolis
   {const p=pp('partenon');if(p)for(let k=0;k<6;k++){const a=R()*TAU,d=rr(12,40),x=p[0]+Math.cos(a)*d,z=p[1]+Math.sin(a)*d;faunaAdd('owl',x,z,{c:{feather:'#8a7a5a',belly:'#e8dcc0',wing:'#6a5a3a',face:'#efe2c8'},beh:'still',s:1.2});}}
   // pelea de codornices en el Ágora
   {const c=[AG.x+40,AG.z-30];for(let k=0;k<2;k++){const F=faunaAdd('quail',c[0]+(k?0.5:-0.5),c[1],{c:{feather:'#8a6a4a',wing:'#6a5a3a',belly:'#e8dcc0'},beh:'still',a:k?Math.PI/2:-Math.PI/2,s:1.6});if(F){F.quail=true;F.y0=floorAt(c[0],c[1]);F.a0=k?Math.PI/2:-Math.PI/2;}}
    for(let k=0;k<9;k++){const a=k/9*TAU,x=c[0]+Math.cos(a)*2.4,z=c[1]+Math.sin(a)*2.4,g=makePerson({chiton:pick(['#e8dfcc','#d7c9ab','#c9b48b']),himation:pick(['#7a5a3a','#4f6a7d','#8a3f2f']),beard:R()<0.6,hair:'#3a2a1e'});g.position.set(x,floorAt(x,z),z);g.rotation.y=Math.atan2(c[0]-x,c[1]-z);scene.add(g);addCirc(x,z,0.4);}
    place('codornices','La pelea de codornices','ΟΡΤΥΓΟΚΟΠΙΑ','Se dibuja un círculo en el suelo y se enfrentan dos codornices; los dueños apuestan, y la que sale del círculo pierde. Hay un juego aún más curioso: golpear con el dedo la cabeza de una codorniz para ver si aguanta sin retroceder. Dicen que a Alcibíades, de joven, se le escapó una codorniz del manto en plena Asamblea.',c[0]+4,c[1]+3,0);}
   // pelea de gallos junto al teatro
   {const t=pp('teatro');if(t){const c=[t[0]+30,t[1]+40];faunaAdd('rooster',c[0]-0.6,c[1],{c:{feather:'#a0402a',tail:'#1a2a20'},beh:'still',a:-Math.PI/2,s:1.1});faunaAdd('rooster',c[0]+0.6,c[1],{c:{feather:'#3a2a20',tail:'#1a2a20'},beh:'still',a:Math.PI/2,s:1.1});
     place('gallos','Las peleas de gallos','ΑΛΕΚΤΡΥΟΝΟΜΑΧΙΑ','Cada año, por ley, la ciudad paga una pelea de gallos en el teatro. Cuentan que Temístocles, camino de la batalla contra los persas, vio pelear a dos gallos y se lo enseñó a sus soldados: «Ellos no luchan por su patria, ni por sus dioses, ni por sus hijos: solo por no ser vencidos». A los gallos de pelea los alimentan con ajo, para hacerlos más bravos.',c[0]+3,c[1]+3,0);}}
   // los pavos reales de una casa rica y un mono con su dueño presumido
   {const p=pp('hefestion');if(p){const c=[p[0]-40,p[1]+30];for(let k=0;k<3;k++)faunaAdd('peacock',c[0]+k*2.2,c[1],{beh:'wander',r:4,extra:['train','fan'],F:{cx:c[0]+2,cz:c[1]}});}
    const w=walkers.find(w=>w.mode==='agora');if(w)faunaAdd('monkey',w.g.position.x+0.8,w.g.position.z,{c:{coat:'#8a7a5a',face:'#e0b8a0'},beh:'follow',F:{lead:w,ox:0.8,oz:0.2},s:1.2});}
  }else{
   // gansos sagrados en el Capitolio
   {const p=pp('ro_jupiter');if(p){for(let k=0;k<7;k++)faunaAdd('goose',p[0]+rr(-6,6)+20,p[1]+rr(-6,6),{c:{feather:'#f2efe8'},r:7,spd:0.8,F:{cx:p[0]+20,cz:p[1]}});
     place('gansos_capitolio','Los gansos de Juno','ANSERES','Estos gansos son sagrados: los cría el Estado junto al templo de Juno. En el 390 a.C., cuando los galos trepaban de noche por la roca del Capitolio, los perros no ladraron, pero los gansos graznaron y despertaron a Marco Manlio, que rechazó el asalto. Desde entonces, los gansos tienen honores y los perros, mala fama.',p[0]+26,p[1]+6,0);}}
   // los pollos sagrados de los augures
   {const p=pp('ro_curia');if(p){const c=[p[0]+14,p[1]+12],gy=floorAt(c[0],c[1]);const cg=grp(c[0],gy,c[1],0);box(2.4,0.08,1.4,lam('#6b4a30'),0,0.04,0,cg);for(let i=0;i<6;i++)box(0.05,1,0.05,lam('#6b4a30'),-1.2+i*0.48,0.5,-0.7,cg);for(let i=0;i<6;i++)box(0.05,1,0.05,lam('#6b4a30'),-1.2+i*0.48,0.5,0.7,cg);box(2.4,0.06,1.4,lam('#8a6a4a'),0,1,0,cg);addBox(c[0],c[1],2.4,1.4,0);
     for(let k=0;k<4;k++)faunaAdd('hen',c[0]+rr(-0.9,0.9),c[1]+rr(-0.4,0.4),{c:{feather:'#efe8dc',wing:'#d8d0c0'},beh:'peck',r:0.8,s:0.9,F:{cx:c[0],cz:c[1],fixedY:true},y:gy+0.08});
     place('pollos_sagrados','Los pollos sagrados','PVLLI','Antes de una batalla o de una asamblea, el pulario abre esta jaula y echa grano a los pollos sagrados. Si comen con tantas ganas que se les cae la comida del pico, los dioses están de acuerdo. En el 249 a.C., el cónsul Claudio Pulcro, ante unos pollos que no querían comer, los tiró al mar: «¡Pues que beban!». Perdió la batalla naval de Drépano.',c[0]+3,c[1]+2,0);}}
   // perro guardián en la entrada de la domus, cerdos del Foro Suario, un loro y un pavo real en el Palatino
   {const p=pp('domus_fauces');if(p)faunaAdd('dog',p[0]+1,p[1]+2,{model:'moloss',info:'moloso',c:{coat:'#2a2018'},beh:'lie'});}
   {const p=pp('ro_palatino');if(p){for(let k=0;k<2;k++)faunaAdd('peacock',p[0]+20+k*3,p[1]+20,{beh:'wander',r:5,extra:['train','fan'],F:{cx:p[0]+21,cz:p[1]+20}});}}
  }
  // la culebra de la casa y, en Roma, un loro en el atrio de tu casa
  if(typeof CASA!=='undefined'&&CASA.X){const y=CASA.Y;faunaAdd('snake',CASA.X+(ro?-3.4:1.4),CASA.Z+(ro?-5.6:3.2),{y,beh:'still',info:'snake',s:1});if(ro){faunaAdd('parrot',CASA.X+4,CASA.Z-6,{y:y+1.2,beh:'still'});const pg=grp(CASA.X+4,y,CASA.Z-6,0);box(0.06,1.2,0.06,lam('#6b4a30'),0,0.6,0,pg);box(0.5,0.04,0.04,lam('#6b4a30'),0,1.2,0,pg);}}
  // también en los destinos: perros y gallinas en cada pueblo
  for(const I of ISLANDS){const t=I.town||I.arrive;if(!t)continue;for(let k=0;k<2;k++){const f=findFree(t.x+rr(-30,30),t.z+rr(-30,30),0.6);faunaAdd('dog',f[0],f[1],{c:{coat:pick(FCOL.dog)},r:20,spd:1.2});}
    const f=findFree(t.x+rr(-25,25),t.z+rr(-25,25),0.6);faunaAdd('rooster',f[0],f[1],{beh:'peck',r:4});for(let k=0;k<3;k++)faunaAdd('hen',f[0]+rr(-2,2),f[1]+rr(-2,2),{c:{feather:pick(FCOL.hen)},beh:'peck',r:4,F:{cx:f[0],cz:f[1]}});}}
function faunaTalk(F){if(F.stray&&F.cur){dogTalk(F);return;}const I=faunaInfo(F.info)||[F.sp,'',''];dlg={n:null};ui='dialog';releasePointer();$('dGlyph').textContent='❦';setName(I[0]);$('dTitle').textContent=MODE==='roma'?'Animales de Roma':'Animales de Atenas';
  $('dBody').innerHTML='<p>'+I[1]+'</p>'+(I[2]?'<p class="sub">Fuentes: '+I[2]+'.</p>':'');const o=$('dOpts');o.innerHTML='';const b=document.createElement('button');b.innerHTML='<span class="n">1</span><span>Seguir mirando</span>';b.onclick=closeDialog;o.appendChild(b);$('dialog').hidden=false;
  state.fauna=state.fauna||{};if(!state.fauna[F.info]){state.fauna[F.info]=1;qAdd('so',1);save();updateStats();}}
